1	/*
2	 * Identity-test kernel - verifies DataCopyPad GM↔UB path works.
3	 * Write expert_flat directly to expanded_expert_idx (first output).
4	 */
5	
6	#include "kernel_operator.h"
7	using namespace AscendC;
8	
9	struct MoeInitRoutingTiling {
10	    int32_t N, K, H, act, tnk, onk, sn, mode, cn;
11	};
12	
13	extern "C" __global__ __aicore__ void moe_init_routing_fp16(
14	    GM_ADDR x, GM_ADDR r, GM_ADDR e,
15	    GM_ADDR ox, GM_ADDR oder, GM_ADDR oe,
16	    GM_ADDR ws, GM_ADDR t)
17	{
18	    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIV_1_0);
19	    if (g_coreType == AIC) return;
20	
21	    auto* tl = reinterpret_cast<__gm__ MoeInitRoutingTiling*>(t);
22	    int32_t tnk = tl->tnk;
23	    int32_t onk = tl->onk;
24	    int32_t H   = tl->H;
25	
26	    GlobalTensor<int32_t> eG, oeG, orG;
27	    GlobalTensor<half> xG, oxG;
28	    eG.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(e), tnk);
29	    oeG.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(oe), onk);
30	    orG.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(oder), onk);
31	    xG.SetGlobalBuffer(reinterpret_cast<__gm__ half*>(x), tnk / tl->K * H);
32	    oxG.SetGlobalBuffer(reinterpret_cast<__gm__ half*>(ox), onk * H);
33	
34	    TPipe pipe;
35	    TQue<QuePosition::VECIN, 1>  inQ;
36	    TQue<QuePosition::VECOUT, 1> outQ;
37	    int64_t bufSz = 2048; // generous buffer
38	    pipe.InitBuffer(inQ,  1, bufSz);
39	    pipe.InitBuffer(outQ, 1, bufSz);
40	
41	    if (GetBlockIdx() == 0) {
42	        // CopyIn: expert_flat → UB
43	        LocalTensor<int32_t> inL = inQ.AllocTensor<int32_t>();
44	        DataCopyExtParams ip{1, static_cast<uint32_t>(tnk * sizeof(int32_t)), 0, 0, 0};
45	        DataCopyPadExtParams<int32_t> pd{false, 0, 0, 0};
46	        DataCopyPad(inL, eG, ip, pd);
47	        inQ.EnQue(inL);
48	
49	        // DeQue → output
50	        LocalTensor<int32_t> inD = inQ.DeQue<int32_t>();
51	
52	        // Write to output via DataCopyPad (proven pattern)
53	        DataCopyParams op; op.blockCount = 1;
54	        op.blockLen = static_cast<uint32_t>(onk * sizeof(int32_t));
55	        DataCopyPad(oeG, inD[0], op);
56	
57	        // Also copy row_flat as-is to orG
58	        // row_flat is at offset N*K elements in the input (but we didn't copy it)
59	        // For now just write -1 to output row
60	        for (int32_t i = 0; i < onk; i++) {
61	            // Use EnQue/DeQue for output
62	        }
63	
64	        // Write x rows as-is (just copy first onk rows from x)
65	        LocalTensor<half> xIn = outQ.AllocTensor<half>();
66	        DataCopyExtParams xp{1, static_cast<uint32_t>(onk * H * sizeof(half)), 0, 0, 0};
67	        DataCopyPadExtParams<half> xpd{false, 0, 0, 0};
68	        DataCopyPad(xIn, xG, xp, xpd);
69	        outQ.EnQue(xIn);
70	        LocalTensor<half> xOut = outQ.DeQue<half>();
71	        DataCopyParams xop; xop.blockCount = 1;
72	        xop.blockLen = static_cast<uint32_t>(onk * H * sizeof(half));
73	        DataCopyPad(oxG, xOut[0], xop);
74	        outQ.FreeTensor(xOut);
75	
76	        inQ.FreeTensor(inD);
77	    }
78	
79	    pipe.Destroy();
80	}
