95	    eG.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(e), tnk);
96	    oeG.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(oe), onk);
97	    orG.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(oder), onk);
98	    xG.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(x), (tnk / tl->K) * H);
99	    oxG.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(ox), onk * H);
100	
101	    TPipe pipe;
102	    TQue<QuePosition::VECIN, 1>  inQ;
103	    TQue<QuePosition::VECOUT, 1> outQ;
104	    int64_t bufSz = 4096;
105	    pipe.InitBuffer(inQ,  1, bufSz);
106	    pipe.InitBuffer(outQ, 1, bufSz);
107	
108	    if (GetBlockIdx() == 0) {
109	        // Copy expert
110	        LocalTensor<int32_t> inL = inQ.AllocTensor<int32_t>();
111	        DataCopyExtParams ip{1, static_cast<uint32_t>(tnk * sizeof(int32_t)), 0, 0, 0};
112	        DataCopyPadExtParams<int32_t> pd{false, 0, 0, 0};
113	        DataCopyPad(inL, eG, ip, pd);
114	        inQ.EnQue(inL);
115	        LocalTensor<int32_t> inD = inQ.DeQue<int32_t>();
116	        DataCopyParams op; op.blockCount = 1;
117	        op.blockLen = static_cast<uint32_t>(onk * sizeof(int32_t));
118	        DataCopyPad(oeG, inD[0], op);
119	
120	        // Copy first onk*H floats from x to ox
121	        LocalTensor<float> xIn = outQ.AllocTensor<float>();
122	        DataCopyExtParams xp{1, static_cast<uint32_t>(onk * H * sizeof(float)), 0, 0, 0};
123	        DataCopyPadExtParams<float> xpd{false, 0, 0, 0};
124	        DataCopyPad(xIn, xG, xp, xpd);
125	        outQ.EnQue(xIn);
126	        LocalTensor<float> xOut = outQ.DeQue<float>();
127	        DataCopyParams xop; xop.blockCount = 1;
128	        xop.blockLen = static_cast<uint32_t>(onk * H * sizeof(float));
129	        DataCopyPad(oxG, xOut[0], xop);
130	        outQ.FreeTensor(xOut);
131	
132	        inQ.FreeTensor(inD);
133	    }
134	    pipe.Destroy();
135	}
