1	/*
2	 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
3	 * MoEInitRouting AscendC kernel: sort + scatter-invert + row-gather.
4	 *
5	 * Uses scalar insertion sort on UB for per-tile sort (max 256 elems).
6	 * Then K-way merge, scatter-invert, and DataCopyPad row gather.
7	 * Key improvement: row gather uses DataCopyPad for bulk H-element copies.
8	 */
9	
10	#include "kernel_operator.h"
11	
12	using namespace AscendC;
13	
14	constexpr int32_t TILE_ELEM = 256;
15	constexpr int32_t BUFFER_NUM = 2;
16	
17	struct TilingData {
18	    int64_t totalFlat;
19	    int64_t N;
20	    int64_t H;
21	    int64_t K;
22	    int64_t dtypeSize;
23	    int64_t numTiles;
24	    int64_t lastTileLen;
25	};
26	
27	template <typename T>
28	class KernelMoeInitRouting {
29	public:
30	    __aicore__ inline KernelMoeInitRouting() {}
31	    __aicore__ inline void Init(
32	        GM_ADDR x, GM_ADDR rowIdx, GM_ADDR expertIdx,
33	        GM_ADDR expandedX, GM_ADDR expandedRowIdx, GM_ADDR expandedExpertIdx,
34	        GM_ADDR workspace, TilingData td, AscendC::TPipe* pipeIn);
35	    __aicore__ inline void Process();
36	
37	private:
38	    __aicore__ inline void SortTile(int64_t start, int64_t len, int64_t ti);
39	    __aicore__ inline void MergeTiles(int64_t totalFlat);
40	    __aicore__ inline void ScatterInvert(int64_t totalFlat);
41	    __aicore__ inline void GatherX(int64_t totalFlat, int64_t N, int64_t H);
42	
43	    AscendC::TPipe* pipe_;
44	    TilingData td_;
45	
46	    GlobalTensor<T> xGm_;
47	    GlobalTensor<int32_t> rowIdxGm_;
48	    GlobalTensor<int32_t> expertIdxGm_;
49	    GlobalTensor<T> expandedXGm_;
50	    GlobalTensor<int32_t> expandedRowIdxGm_;
51	    GlobalTensor<int32_t> expandedExpertIdxGm_;
52	    GlobalTensor<int32_t> wsGm_;
53	
54	    TQue<TPosition::VECIN, 1> sortBufQ_;
55	    TQue<TPosition::VECIN, BUFFER_NUM> rowQ_;
56	};
57	
58	template <typename T>
59	__aicore__ inline void KernelMoeInitRouting<T>::Init(
60	    GM_ADDR x, GM_ADDR rowIdx, GM_ADDR expertIdx,
61	    GM_ADDR expandedX, GM_ADDR expandedRowIdx, GM_ADDR expandedExpertIdx,
62	    GM_ADDR workspace, TilingData td, AscendC::TPipe* pipeIn)
63	{
64	    pipe_ = pipeIn;
65	    td_ = td;
66	
67	    xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x), td.N * td.H);
68	    rowIdxGm_.SetGlobalBuffer(
69	        reinterpret_cast<__gm__ int32_t*>(rowIdx), td.totalFlat);
70	    expertIdxGm_.SetGlobalBuffer(
71	        reinterpret_cast<__gm__ int32_t*>(expertIdx), td.totalFlat);
72	    expandedXGm_.SetGlobalBuffer(
73	        reinterpret_cast<__gm__ T*>(expandedX), td.totalFlat * td.H);
74	    expandedRowIdxGm_.SetGlobalBuffer(
75	        reinterpret_cast<__gm__ int32_t*>(expandedRowIdx), td.totalFlat);
76	    expandedExpertIdxGm_.SetGlobalBuffer(
77	        reinterpret_cast<__gm__ int32_t*>(expandedExpertIdx), td.totalFlat);
78	
79	    /* Workspace: enough for sort data (2 * numTiles * TILE_ELEM) + temp */
80	    int64_t wsSize = td.numTiles * TILE_ELEM * 2 + td.totalFlat + 64;
81	    wsGm_.SetGlobalBuffer(
82	        reinterpret_cast<__gm__ int32_t*>(workspace), wsSize);
83	
84	    /* UB buffer for row copy: must hold H elements of type T (max H up to 4608) */
85	    int64_t rowBufSize = td.H * sizeof(T) + 4096;  /* +4096 for alignment/padding */
86	    pipe_->InitBuffer(sortBufQ_, 1, TILE_ELEM * 3 * sizeof(int32_t));
87	    pipe_->InitBuffer(rowQ_, BUFFER_NUM, rowBufSize);
88	}
89	
90	template <typename T>
91	__aicore__ inline void KernelMoeInitRouting<T>::SortTile(
92	    int64_t start, int64_t len, int64_t ti)
93	{
94	    int64_t K = td_.K;
95	    int64_t expertWsBase = td_.numTiles * TILE_ELEM;
96	    LocalTensor<int32_t> buf = sortBufQ_.AllocTensor<int32_t>();
97	
98	    /* Load flattened [N,K]→[N*K] expert+row into UB */
99	    for (int64_t j = 0; j < len; j++) {
100	        int64_t p = start + j;
101	        int64_t r = p / K;
102	        int64_t c = p % K;
103	        buf.SetValue(j, expertIdxGm_.GetValue(r * K + c));
104	        buf.SetValue(TILE_ELEM + j, rowIdxGm_.GetValue(r * K + c));
105	    }
106	
107	    /* Insertion sort by expert value (ascending, stable) */
108	    for (int64_t i = 1; i < len; i++) {
109	        int32_t keyE = buf.GetValue(i);
110	        int32_t keyR = buf.GetValue(TILE_ELEM + i);
111	        int64_t jj = i - 1;
112	        while (jj >= 0 && buf.GetValue(jj) > keyE) {
113	            buf.SetValue(jj + 1, buf.GetValue(jj));
114	            buf.SetValue(TILE_ELEM + jj + 1,
115	                buf.GetValue(TILE_ELEM + jj));
116	            jj--;
117	        }
118	        buf.SetValue(jj + 1, keyE);
119	        buf.SetValue(TILE_ELEM + jj + 1, keyR);
120	    }
121	
122	    /* Write sorted results to output and workspace */
123	    for (int64_t j = 0; j < len; j++) {
124	        int32_t ev = buf.GetValue(j);
125	        int32_t rv = buf.GetValue(TILE_ELEM + j);
126	        expandedExpertIdxGm_.SetValue(start + j, ev);
127	        expandedRowIdxGm_.SetValue(start + j, rv);
128	        /* Workspace: expert at upper half, row at lower half */
129	        wsGm_.SetValue(expertWsBase + ti * TILE_ELEM + j, ev);
130	        wsGm_.SetValue(ti * TILE_ELEM + j, rv);
131	    }
132	
133	    sortBufQ_.FreeTensor(buf);
134	}
135	
136	template <typename T>
137	__aicore__ inline void KernelMoeInitRouting<T>::MergeTiles(int64_t totalFlat)
138	{
139	    int64_t expertBase = td_.numTiles * TILE_ELEM;
140	
141	    if (td_.numTiles <= 1) {
142	        /* Single tile: just copy from workspace expert region */
143	        for (int64_t j = 0; j < totalFlat; j++) {
144	            expandedExpertIdxGm_.SetValue(j,
145	                wsGm_.GetValue(expertBase + j));
146	            expandedRowIdxGm_.SetValue(j,
147	                wsGm_.GetValue(j));
148	        }
149	        return;
150	    }
151	
152	    /* K-way merge: track position in each sorted tile */
153	    int64_t ptrs[55];
154	    int64_t ends[55];
155	    for (int64_t i = 0; i < td_.numTiles; i++) {
156	        ptrs[i] = expertBase + i * TILE_ELEM;
157	        int64_t tlen = (i == td_.numTiles - 1) ? td_.lastTileLen : TILE_ELEM;
158	        ends[i] = expertBase + i * TILE_ELEM + tlen;
159	    }
160	
161	    for (int64_t outPos = 0; outPos < totalFlat; outPos++) {
162	        int32_t minVal = 2147483647;
163	        int64_t minTile = -1;
164	        for (int64_t ti = 0; ti < td_.numTiles; ti++) {
165	            if (ptrs[ti] < ends[ti]) {
166	                int32_t v = wsGm_.GetValue(ptrs[ti]);
167	                if (v < minVal) { minVal = v; minTile = ti; }
168	            }
169	        }
170	        if (minTile < 0) break;
171	
172	        int64_t off = ptrs[minTile] - expertBase - minTile * TILE_ELEM;
173	        expandedExpertIdxGm_.SetValue(outPos, minVal);
174	        expandedRowIdxGm_.SetValue(outPos,
175	            wsGm_.GetValue(minTile * TILE_ELEM + off));
176	        ptrs[minTile]++;
177	    }
178	}
