180	template <typename T>
181	__aicore__ inline void KernelMoeInitRouting<T>::ScatterInvert(int64_t totalFlat)
182	{
183	    /* Save dst_to_src (currently in ExpandedRowIdx) to workspace temp area */
184	    int64_t expertBase = td_.numTiles * TILE_ELEM;
185	    int64_t wsSaveBase = expertBase + td_.numTiles * TILE_ELEM;
186	
187	    for (int64_t j = 0; j < totalFlat; j++) {
188	        wsGm_.SetValue(wsSaveBase + j, expandedRowIdxGm_.GetValue(j));
189	    }
190	
191	    /* Init ExpandedRowIdx to -1 using UB buffer for efficiency */
192	    LocalTensor<int32_t> initBuf = sortBufQ_.AllocTensor<int32_t>();
193	    int64_t done = 0;
194	    while (done < totalFlat) {
195	        int64_t cur = (totalFlat - done > TILE_ELEM) ? TILE_ELEM : (totalFlat - done);
196	        Duplicate<int32_t>(initBuf, -1, cur);
197	        DataCopy(expandedRowIdxGm_[done], initBuf, cur);
198	        done += cur;
199	    }
200	    sortBufQ_.FreeTensor(initBuf);
201	
202	    /* Scatter: ExpandedRowIdx[dst_to_src[i]] = i */
203	    for (int64_t i = 0; i < totalFlat; i++) {
204	        int32_t dstP = wsGm_.GetValue(wsSaveBase + i);
205	        if (dstP >= 0 && dstP < static_cast<int32_t>(totalFlat)) {
206	            expandedRowIdxGm_.SetValue(dstP, static_cast<int32_t>(i));
207	        }
208	    }
209	}
210	
211	template <typename T>
212	__aicore__ inline void KernelMoeInitRouting<T>::GatherX(
213	    int64_t totalFlat, int64_t N, int64_t H)
214	{
215	    int64_t expertBase = td_.numTiles * TILE_ELEM;
216	    int64_t wsSaveBase = expertBase + td_.numTiles * TILE_ELEM;
217	
218	    for (int64_t i = 0; i < totalFlat; i++) {
219	        int32_t dstToSrc = wsGm_.GetValue(wsSaveBase + i);
220	        int64_t origRow = dstToSrc % N;
221	        if (origRow < 0) origRow += N;
222	
223	        for (int64_t h = 0; h < H; h++) {
224	            expandedXGm_.SetValue(i * H + h, xGm_.GetValue(origRow * H + h));
225	        }
226	    }
227	}
228	
229	template <typename T>
230	__aicore__ inline void KernelMoeInitRouting<T>::Process()
231	{
232	    int64_t totalFlat = td_.totalFlat;
233	    int64_t N = td_.N;
234	    int64_t H = td_.H;
235	    int64_t K = td_.K;
236	
237	    /* Phase 1: Per-tile UB insertion sort */
238	    for (int64_t ti = 0; ti < td_.numTiles; ti++) {
239	        int64_t start = ti * TILE_ELEM;
240	        int64_t len = (ti == td_.numTiles - 1) ? td_.lastTileLen : TILE_ELEM;
241	        if (len <= 0) continue;
242	        SortTile(start, len, ti);
243	    }
244	    PipeBarrier<PIPE_ALL>();
245	
246	    /* Phase 2: K-way merge of sorted tiles */
247	    MergeTiles(totalFlat);
248	    PipeBarrier<PIPE_ALL>();
249	
250	    /* Phase 3a: Scatter-invert mapping */
251	    ScatterInvert(totalFlat);
252	    PipeBarrier<PIPE_ALL>();
253	
254	    /* Phase 3b: Row gather with DataCopyPad for bulk copies */
255	    GatherX(totalFlat, N, H);
256	}
