258	extern "C" __global__ __aicore__ void moe_init_routing(
259	    GM_ADDR x, GM_ADDR row_idx, GM_ADDR expert_idx,
260	    GM_ADDR expanded_x, GM_ADDR expanded_row_idx, GM_ADDR expanded_expert_idx,
261	    GM_ADDR workspace, GM_ADDR tiling)
262	{
263	    auto* gmT = reinterpret_cast<__gm__ TilingData*>(tiling);
264	    TilingData td;
265	    td.totalFlat = gmT->totalFlat;
266	    td.N = gmT->N;
267	    td.H = gmT->H;
268	    td.K = gmT->K;
269	    td.dtypeSize = gmT->dtypeSize;
270	    td.numTiles = gmT->numTiles;
271	    td.lastTileLen = gmT->lastTileLen;
272	
273	    if (td.dtypeSize == 2) {
274	        AscendC::TPipe pipe;
275	        KernelMoeInitRouting<half> op;
276	        op.Init(x, row_idx, expert_idx, expanded_x, expanded_row_idx,
277	                expanded_expert_idx, workspace, td, &pipe);
278	        op.Process();
279	    } else {
280	        AscendC::TPipe pipe;
281	        KernelMoeInitRouting<float> op;
282	        op.Init(x, row_idx, expert_idx, expanded_x, expanded_row_idx,
283	                expanded_expert_idx, workspace, td, &pipe);
284	        op.Process();
285	    }
286	}
