16	    int64_t totalFlat;
17	    int64_t N;
18	    int64_t H;
19	    int64_t K;
20	    int64_t dtypeSize;
21	    int64_t numTiles;
22	    int64_t lastTileLen;
23	};
24	
25	std::tuple<at::Tensor, at::Tensor, at::Tensor> moe_init_routing(
26	    const at::Tensor& x, const at::Tensor& row_idx,
27	    const at::Tensor& expert_idx, int64_t active_num)
28	{
29	    TORCH_CHECK(x.dim() == 2, "x must be 2D (N, H)");
30	    TORCH_CHECK(row_idx.dim() == 2, "row_idx must be 2D (N, K)");
31	    TORCH_CHECK(expert_idx.dim() == 2, "expert_idx must be 2D (N, K)");
32	    TORCH_CHECK(row_idx.size(0) == expert_idx.size(0) &&
33	                row_idx.size(1) == expert_idx.size(1),
34	                "row_idx and expert_idx must have same shape");
35	    TORCH_CHECK(x.size(0) == expert_idx.size(0),
36	                "x and expert_idx must have same N dimension");
37	
38	    int64_t N = x.size(0);
39	    int64_t H = x.size(1);
40	    int64_t K = expert_idx.size(1);
41	    int64_t totalFlat = N * K;
42	
43	    int64_t dtypeSizeVal = 0;
44	    if (x.scalar_type() == at::kFloat) {
45	        dtypeSizeVal = 4;
46	    } else if (x.scalar_type() == at::kHalf || x.scalar_type() == at::kBFloat16) {
47	        dtypeSizeVal = 2;
48	    } else {
49	        TORCH_CHECK(false, "Unsupported x dtype, must be float32/float16/bfloat16");
50	    }
51	
52	    at::Tensor expanded_x = at::empty({totalFlat, H}, x.options());
53	    at::Tensor expanded_row_idx = at::empty({totalFlat},
54	        x.options().dtype(at::kInt));
55	    at::Tensor expanded_expert_idx = at::empty({totalFlat},
56	        x.options().dtype(at::kInt));
57	
58	    constexpr int64_t TILE_ELEM = 256;
59	    int64_t numTilesVal = (totalFlat + TILE_ELEM - 1) / TILE_ELEM;
60	    if (numTilesVal < 1) numTilesVal = 1;
61	    int64_t lastTileLenVal = totalFlat - (numTilesVal - 1) * TILE_ELEM;
62	
63	    TilingData tiling;
64	    tiling.totalFlat = totalFlat;
65	    tiling.N = N;
66	    tiling.H = H;
67	    tiling.K = K;
68	    tiling.dtypeSize = dtypeSizeVal;
69	    tiling.numTiles = numTilesVal;
70	    tiling.lastTileLen = lastTileLenVal;
71	
72	    at::Tensor tilingCpu = at::empty(
73	        {static_cast<int64_t>(sizeof(TilingData))},
74	        at::device(at::kCPU).dtype(at::kByte));
75	    *reinterpret_cast<TilingData*>(tilingCpu.data_ptr()) = tiling;
76	    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);
77	
78	    /* Workspace:
79	     *   Part 1: [0, numTiles*TILE_ELEM) sorted expert values per tile
80	     *   Part 2: [numTiles*TILE_ELEM, numTiles*TILE_ELEM+2*numTiles*TILE_ELEM)
81	     *           sorted row values per tile
82	     *   Part 3: saved dst_to_src and tmp
83	     */
84	    int64_t wsBytes = numTilesVal * TILE_ELEM * sizeof(int32_t) * 2 +
85	                      totalFlat * sizeof(int32_t) + 4096;
86	    at::Tensor workspace = at::empty({wsBytes}, x.options().dtype(at::kByte));
87	
88	    uint32_t blockDim = 1;
89	    EXEC_KERNEL_CMD(moe_init_routing, blockDim,
90	        x, row_idx, expert_idx, expanded_x, expanded_row_idx,
91	        expanded_expert_idx, workspace, tilingNpu);
92	
93	    return std::make_tuple(expanded_x, expanded_row_idx, expanded_expert_idx);
94	}
