45	class FullLoadSort {
46	public:
47	    __aicore__ inline FullLoadSort() {}
48	    __aicore__ inline void Init(GM_ADDR input, GM_ADDR output,
49	                                 const SortTiling* tiling, TPipe* pipe);
50	    __aicore__ inline void Process();
51	
52	protected:
53	    __aicore__ inline void ProcessOneRow(int64_t row);
54	
55	    TPipe* pipe;
56	    TQue<QuePosition::VECIN, 1> copyInQueue;
57	    TQue<QuePosition::VECOUT, 1> copyOutQueue;
58	    TBuf<TPosition::VECCALC> tempBuffer;
59	    TBuf<TPosition::VECCALC> sortedBuffer;
60	    GlobalTensor<float> inputGm;
61	    GlobalTensor<float> outputGm;
