67	__aicore__ inline void FullLoadSort::Init(
68	    GM_ADDR input, GM_ADDR output, const SortTiling* tiling, TPipe* tPipe)
69	{
70	    this->pipe = tPipe;
71	    this->sortLen = tiling->sortLen;
72	    this->sortNum = tiling->sortNum;
73	    this->batchCount = tiling->batchCount;
74	    this->coreNum = tiling->coreNum;
75	    this->descending = (tiling->descending != 0);
76	    this->dtypeSize = tiling->dtypeSize;
77	    this->isFloat16 = tiling->isFloat16;
78	
79	    int64_t totalBytes = this->batchCount * this->sortLen * this->dtypeSize;
80	    inputGm.SetGlobalBuffer((__gm__ float*)input, totalBytes / sizeof(float));
81	    outputGm.SetGlobalBuffer((__gm__ float*)output, totalBytes / sizeof(float));
82	
83	    int64_t bufSize = this->sortNum * sizeof(float) * 2;
84	    pipe->InitBuffer(copyInQueue, 1, bufSize);
85	    pipe->InitBuffer(copyOutQueue, 1, bufSize);
86	    pipe->InitBuffer(tempBuffer, bufSize);
87	    pipe->InitBuffer(sortedBuffer, bufSize);
88	}
