90	__aicore__ inline void FullLoadSort::ProcessOneRow(int64_t row) {
91	    int64_t byteLen = this->sortLen * this->dtypeSize;
92	    int64_t gmOff = row * this->sortLen;
93	    int64_t sn = this->sortNum;
94	
95	    // --- CopyIn ---
96	    LocalTensor<float> inLocal = copyInQueue.AllocTensor<float>();
97	    DataCopyParams cp;
98	    cp.blockCount = 1;
99	    cp.blockLen = static_cast<uint32_t>(byteLen);
100	    DataCopyPadParams pp{false, 0, 0, 0};
101	    DataCopyPad(inLocal[0], inputGm[gmOff], cp, pp);
102	    // Copy companion values from same GM data
103	    DataCopyPad(inLocal[sn], inputGm[gmOff], cp, pp);
104	    copyInQueue.EnQue(inLocal);
105	
106	    // --- SortCompute ---
107	    inLocal = copyInQueue.DeQue<float>();
108	    LocalTensor<float> keysFp32 = inLocal[0];
109	
110	    // Cast to float32 if non-float input
111	    if (isFloat16 == 1) {
112	        LocalTensor<half> halfIn = inLocal.ReinterpretCast<half>();
113	        Cast(keysFp32, halfIn, RoundMode::CAST_NONE, sn);
114	    } else if (isFloat16 == 2) {
115	        LocalTensor<bfloat16_t> bf16In = inLocal.ReinterpretCast<bfloat16_t>();
116	        Cast(keysFp32, bf16In, RoundMode::CAST_NONE, sn);
117	    }
118	
119	    // For fp16/bf16, companion area needs sn uint32_t values but CopyIn only
120	    // loaded sortLen half/bf16 elements. Fill companion with zero-initialized
121	    // values (Sort companion carries opaque uint32 data alongside keys).
122	    if (isFloat16 > 0) {
123	        LocalTensor<uint32_t> valsDest = inLocal[sn].ReinterpretCast<uint32_t>();
124	        for (int64_t i = 0; i < sn; i++) {
125	            valsDest.SetValue(i, (uint32_t)0);
126	        }
127	    }
128	
129	    // Negate if ascending (Sort instruction is descending)
130	    if (!descending) {
131	        Muls(keysFp32, keysFp32, (float)-1.0, sn);
132	    }
133	
134	    // Pad tail with MIN_FP32
135	    int64_t dupNum = this->sortLen % ONE_REPEAT_SORT_NUM;
136	    if (dupNum > 0) {
137	        int dupIdx = this->sortLen - dupNum;
138	        uint64_t mask0 = UINT64_MAX;
139	        mask0 = mask0 << dupNum;
140	        mask0 = mask0 & (UINT64_MAX >> ONE_REPEAT_SORT_NUM);
141	        uint64_t mask[2] = {mask0, 0};
142	        Duplicate(keysFp32[dupIdx], MIN_FP32, mask, 1, DST_BLK_STRIDE, DST_REP_STRIDE);
143	    }
144	
145	    // Concat → Sort → Extract
146	    LocalTensor<float> concatLocal;
147	    LocalTensor<float> tmpBuf = tempBuffer.Get<float>(GetSortLen<float>(sn));
148	    Concat(concatLocal, keysFp32, tmpBuf, sn / ONE_REPEAT_SORT_NUM);
149	
150	    LocalTensor<float> sortedLocal = sortedBuffer.Get<float>(GetSortLen<float>(sn));

150	    LocalTensor<float> sortedLocal = sortedBuffer.Get<float>(GetSortLen<float>(sn));
151	    LocalTensor<uint32_t> valsLocal = inLocal[sn].ReinterpretCast<uint32_t>();
152	    Sort<float, true>(sortedLocal, concatLocal, valsLocal, tmpBuf,
153	                      sn / ONE_REPEAT_SORT_NUM);
154	
155	    LocalTensor<float> outLocal = copyOutQueue.AllocTensor<float>();
156	    LocalTensor<float> sortedKeys = outLocal[0];
157	    LocalTensor<uint32_t> sortedVals = outLocal[sn].ReinterpretCast<uint32_t>();
158	    Extract(sortedKeys, sortedVals, sortedLocal, sn / ONE_REPEAT_SORT_NUM);
159	
160	    // Negate back if ascending
161	    if (!descending) {
162	        Muls(sortedKeys, sortedKeys, (float)-1.0, this->sortLen);
163	    }
164	
165	    // Cast back to original dtype
166	    if (isFloat16 == 1) {
167	        LocalTensor<half> halfOut = sortedKeys.ReinterpretCast<half>();
168	        Cast(halfOut, sortedKeys, RoundMode::CAST_ROUND, this->sortLen);
169	    } else if (isFloat16 == 2) {
170	        LocalTensor<bfloat16_t> bf16Out = sortedKeys.ReinterpretCast<bfloat16_t>();
171	        Cast(bf16Out, sortedKeys, RoundMode::CAST_ROUND, this->sortLen);
172	    }
173	
174	    copyOutQueue.EnQue<float>(outLocal);
175	    copyInQueue.FreeTensor(inLocal);
176	
177	    // --- CopyOut ---
178	    outLocal = copyOutQueue.DeQue<float>();
179	    DataCopyPad(outputGm[gmOff], outLocal[0], cp);
180	    copyOutQueue.FreeTensor(outLocal);
181	}
