183	__aicore__ inline void FullLoadSort::Process() {
184	    int64_t blockIdx = GetBlockIdx();
185	    if (blockIdx >= this->coreNum) return;
186	
187	    for (int64_t row = blockIdx; row < this->batchCount; row += this->coreNum) {
188	        ProcessOneRow(row);
189	    }
190	    if (this->coreNum > 1) {
191	        SyncAll();
192	    }
193	}
