{"content": "/*
 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
 * Licensed under the CANN Open Software License Agreement Version 2.0.
 *
 * MoE Init Routing AscendC kernel.
 * Fuses: stable-sort (expert_idx ascending, carry row_idx via hardware Sort)
 *        + scatter-invert (src_to_dst[dst_to_src[i]] = i)
 *        + row-gather (expanded_x[p] = x[dst_to_src[p] % N])
 * Two modes based on total N*K vs UB_SORT_CAPACITY (2048):
 *   fullload: single-pass hardware Sort on UB
 *   singlecore: multi-tile sort with K-way merge (uses GM workspace)
 */

#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t ONE_REPEAT_SORT_NUM = 32;
constexpr int64_t BLOCK_BYTES = 32;
constexpr int64_t DST_BLK_STRIDE = 1;
constexpr int64_t DST_REP_STRIDE = 8;
constexpr float MIN_FP32 = -3.4e38f;
constexpr int64_t UB_SORT_CAPACITY = 2048;

struct MoeInitRoutingTiling {
    int32_t N, K, H, totalFlat, outputNK, sortNum, mode;
};

template <typename T>
class KernelMoeInitRouting {
public:
    __aicore__ inline KernelMoeInitRouting() {}
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR r, GM_ADDR e,
        GM_ADDR ox, GM_ADDR oder, GM_ADDR oe,
        GM_ADDR ws, GM_ADDR t, TPipe* pipeIn);
    __aicore__ inline void Process();

private:
    __aicore__ inline void FullloadSort();
    __aicore__ inline void SingleSort();

    TPipe* pipe_;
    MoeInitRoutingTiling td_;

    GlobalTensor<T> xGm_;
    GlobalTensor<int32_t> rGm_;
    GlobalTensor<int32_t> eGm_;
    GlobalTensor<T> oxGm_;
    GlobalTensor<int32_t> orGm_;
    GlobalTensor<int32_t> oeGm_;
    GlobalTensor<int32_t> wsGm_;

    // UB queues for sort
    TQue<QuePosition::VECIN, 1> sortInQ_;
    TQue<QuePosition::VECOUT, 1> sortOutQ_;
    TBuf<TPosition::VECCALC> sortTmpBuf_;
    TBuf<TPosition::VECCALC> sortOutBuf_;
};

template <typename T>
__aicore__ inline void KernelMoeInitRouting<T>::Init(
    GM_ADDR x, GM_ADDR r, GM_ADDR e,
    GM_ADDR ox, GM_ADDR oder, GM_ADDR oe,
    GM_ADDR ws, GM_ADDR t, TPipe* pipeIn)
{
    pipe_ = pipeIn;
    auto* tl = reinterpret_cast<__gm__ MoeInitRoutingTiling*>(t);
    td_.N = tl->N;
    td_.K = tl->K;
    td_.H = tl->H;
    td_.totalFlat = tl->totalFlat;
    td_.outputNK = tl->outputNK;
    td_.sortNum = tl->sortNum;
    td_.mode = tl->mode;

    xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x), td_.N * td_.H);
    rGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(r), td_.totalFlat);
    eGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(e), td_.totalFlat);
    oxGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(ox), td_.outputNK * td_.H);
    orGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(oder), td_.outputNK);
    oeGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(oe), td_.outputNK);

    int64_t wsElems = td_.totalFlat * 4 + 256;
    wsGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(ws), wsElems);

    int64_t sortBufSize = td_.sortNum * sizeof(float) * 4;
    pipe_->InitBuffer(sortInQ_,  1, sortBufSize);
    pipe_->InitBuffer(sortOutQ_, 1, sortBufSize);
    pipe_->InitBuffer(sortTmpBuf_, sortBufSize);
    pipe_->InitBuffer(sortOutBuf_, sortBufSize);
}

// ============================================================================
// FullloadSort: single-pass hardware Sort on UB
// ============================================================================
template <typename T>
__aicore__ inline void KernelMoeInitRouting<T>::FullloadSort()
{
    int64_t totalFlat = td_.totalFlat;
    int64_t outputNK  = td_.outputNK;
    int64_t sortNum   = td_.sortNum;
    int64_t H         = td_.H;
    int64_t N         = td_.N;

    // Allocate input buffer: keys + values interleaved
    LocalTensor<float> inLocal = sortInQ_.AllocTensor<float>();
    LocalTensor<float> keysFp32 = inLocal[0];
    LocalTensor<int32_t> keysInt32 = keysFp32.ReinterpretCast<int32_t>();
    LocalTensor<uint32_t> valsLocal = inLocal[sortNum].ReinterpretCast<uint32_t>();

    // CopyIn: load flattened expert_idx and row_idx
    DataCopyParams cp;
    cp.blockCount = 1;
    cp.blockLen = static_cast<uint32_t>(totalFlat * sizeof(int32_t));
    DataCopyPadParams pp{false, 0, 0, 0};
    DataCopyPad(keysInt32[0], eGm_[0], cp, pp);
    {
        LocalTensor<int32_t> rTmp = valsLocal.ReinterpretCast<int32_t>();
        DataCopyPad(rTmp[0], rGm_[0], cp, pp);
    }

    // Cast expert int32 -> float32, negate for ascending (Sort is descending)
    Cast(keysFp32, keysInt32, RoundMode::CAST_NONE, sortNum);
    Muls(keysFp32, keysFp32, static_cast<float>(-1.0), sortNum);

    // Pad tail elements with MIN_FP32
    int64_t dupNum = totalFlat % ONE_REPEAT_SORT_NUM;
    if (dupNum > 0) {
        int64_t dupIdx = totalFlat - dupNum;
        uint64_t mask0 = UINT64_MAX;
        mask0 = mask0 << dupNum;
        mask0 = mask0 & (UINT64_MAX >> ONE_REPEAT_SORT_NUM);
        uint64_t mask[2] = {mask0, 0};
        Duplicate(keysFp32[dupIdx], MIN_FP32, mask, 1, DST_BLK_STRIDE, DST_REP_STRIDE);
    }

    // Concat -> Sort<float,true> -> Extract
    LocalTensor<float> concatLocal;
    LocalTensor<float> tmpBuf = sortTmpBuf_.Get<float>(GetSortLen<float>(sortNum));
    Concat(concatLocal, keysFp32, tmpBuf, sortNum / ONE_REPEAT_SORT_NUM);

    LocalTensor<float> sortedLocal = sortOutBuf_.Get<float>(GetSortLen<float>(sortNum));
    Sort<float, true>(sortedLocal, concatLocal, valsLocal, tmpBuf,
                      sortNum / ONE_REPEAT_SORT_NUM);

    // Extract sorted keys + values
    LocalTensor<float> outLocal = sortOutQ_.AllocTensor<float>();
    LocalTensor<float> sortedKeys = outLocal[0];
    LocalTensor<uint32_t> sortedVals = outLocal[sortNum].ReinterpretCast<uint32_t>();
    Extract(sortedKeys, sortedVals, sortedLocal, sortNum / ONE_REPEAT_SORT_NUM);

    // Negate keys back (restore ascending order), cast to int32
    Muls(sortedKeys, sortedKeys, static_cast<float>(-1.0), totalFlat);
    LocalTensor<int32_t> sortedKeysInt = sortedKeys.ReinterpretCast<int32_t>();
    Cast(sortedKeysInt, sortedKeys, RoundMode::CAST_ROUND, sortNum);

    // CopyOut expanded_expert_idx = sortedKeysInt[:outputNK]
    DataCopyParams cpOut;
    cpOut.blockCount = 1;
    cpOut.blockLen = static_cast<uint32_t>(outputNK * sizeof(int32_t));
    DataCopyPad(oeGm_[0], sortedKeysInt[0], cpOut);

    // Save dst_to_src (sorted row values) to workspace for post-processing
    LocalTensor<int32_t> dstToSrcUb = sortedVals.ReinterpretCast<int32_t>();
    // Write first outputNK as dst_to_src (needed for scatter-invert + gather)
    DataCopyPad(wsGm_[0], dstToSrcUb[0], cpOut);
    // Also save full list for reference
    DataCopyParams cpFull;
    cpFull.blockCount = 1;
    cpFull.blockLen = static_cast<uint32_t>(totalFlat * sizeof(int32_t));
    DataCopyPad(wsGm_[outputNK], dstToSrcUb[0], cpFull);

    sortOutQ_.EnQue<float>(outLocal);
    sortInQ_.FreeTensor(inLocal);

    // DeQue output
    LocalTensor<float> outD = sortOutQ_.DeQue<float>();
    sortOutQ_.FreeTensor(outD);

    PipeBarrier<PIPE_ALL>();

    // ---- Post-process Phase 1: Scatter-invert ----
    // Initialize orGm_ (expanded_row_idx) to -1
    LocalTensor<int32_t> initBuf = sortInQ_.AllocTensor<int32_t>();
    Duplicate<int32_t>(initBuf, -1, outputNK);
    DataCopyParams cpInit;
    cpInit.blockCount = 1;
    cpInit.blockLen = static_cast<uint32_t>(outputNK * sizeof(int32_t));
    DataCopyPad(orGm_[0], initBuf[0], cpInit);
    sortInQ_.FreeTensor(initBuf);

    // Scatter: orGm_[dst_to_src[i]] = i
    for (int64_t i = 0; i < outputNK; i++) {
        int32_t dstP = wsGm_.GetValue(i);
        if (dstP >= 0 && dstP < static_cast<int32_t>(totalFlat)) {
            orGm_.SetValue(dstP, static_cast<int32_t>(i));
        }
    }
    PipeBarrier<PIPE_ALL>();

    // ---- Post-process Phase 2: Gather x rows ----
    // For each output position, copy x[dst_to_src[i] % N, :] -> expanded_x[i, :]
    for (int64_t i = 0; i < outputNK; i++) {
        int32_t srcIdx = wsGm_.GetValue(i);
        int64_t origRow = srcIdx % N;
        if (origRow < 0) origRow += N;

        LocalTensor<T> xRow = sortInQ_.AllocTensor<T>();
        DataCopyParams cpRow;
        cpRow.blockCount = 1;
        cpRow.blockLen = static_cast<uint32_t>(H * sizeof(T));
        DataCopyPadParams ppRow{false, 0, 0, 0};
        DataCopyPad(xRow[0], xGm_[origRow * H], cpRow, ppRow);
        sortInQ_.EnQue(xRow);
        LocalTensor<T> xRowD = sortInQ_.DeQue<T>();
        DataCopyPad(oxGm_[i * H], xRowD[0], cpRow);
        sortInQ_.FreeTensor(xRowD);
    }
}

// ============================================================================
// SingleSort: multi-tile sort with K-way merge
// ============================================================================
template <typename T>
__aicore__ inline void KernelMoeInitRouting<T>::SingleSort()
{
    int64_t totalFlat = td_.totalFlat;
    int64_t outputNK  = td_.outputNK;
    int64_t N         = td_.N;
    int64_t H         = td_.H;

    int64_t sortNumPerTile = UB_SORT_CAPACITY;
    int64_t tileSn = ((sortNumPerTile + ONE_REPEAT_SORT_NUM - 1)
                        / ONE_REPEAT_SORT_NUM) * ONE_REPEAT_SORT_NUM;
    int64_t numTiles = (totalFlat + sortNumPerTile - 1) / sortNumPerTile;

    // Workspace layout:
    //   [0, numTiles*tileSn): sorted expert keys per tile (int32)
    //   [numTiles*tileSn, 2*numTiles*tileSn): sorted row values per tile (int32)
    //   [2*numTiles*tileSn, ...): merged dst_to_src (int32)
    int64_t wsExpertBase = 0;
    int64_t wsRowBase = numTiles * tileSn;
    int64_t wsDstSave = wsRowBase + numTiles * tileSn;

    // Phase 1: Per-tile sort
    for (int64_t ti = 0; ti < numTiles; ti++) {
        int64_t start = ti * sortNumPerTile;
        int64_t len = (ti == numTiles - 1) ? (totalFlat - start) : sortNumPerTile;
        if (len <= 0) continue;

        LocalTensor<float> inTile = sortInQ_.AllocTensor<float>();
        LocalTensor<float> keysTileFp32 = inTile[0];
        LocalTensor<int32_t> keysTileInt = keysTileFp32.ReinterpretCast<int32_t>();
        LocalTensor<uint32_t> valsTile = inTile[tileSn].ReinterpretCast<uint32_t>();

        DataCopyParams cpTile;
        cpTile.blockCount = 1;
        cpTile.blockLen = static_cast<uint32_t>(len * sizeof(int32_t));
        DataCopyPadParams ppTile{false, 0, 0, 0};
        DataCopyPad(keysTileInt[0], eGm_[start], cpTile, ppTile);
        {
            LocalTensor<int32_t> rTmp = valsTile.ReinterpretCast<int32_t>();
            DataCopyPad(rTmp[0], rGm_[start], cpTile, ppTile);
        }

        Cast(keysTileFp32, keysTileInt, RoundMode::CAST_NONE, tileSn);
        Muls(keysTileFp32, keysTileFp32, static_cast<float>(-1.0), tileSn);

        int64_t dupN = len % ONE_REPEAT_SORT_NUM;
        if (dupN > 0) {
            int64_t dupIdx = len - dupN;
            uint64_t mask0 = UINT64_MAX;
            mask0 = mask0 << dupN;
            mask0 = mask0 & (UINT64_MAX >> ONE_REPEAT_SORT_NUM);
            uint64_t mask[2] = {mask0, 0};
            Duplicate(keysTileFp32[dupIdx], MIN_FP32, mask, 1, DST_BLK_STRIDE, DST_REP_STRIDE);
        }

        LocalTensor<float> concatLocal;
        LocalTensor<float> tmpBuf = sortTmpBuf_.Get<float>(GetSortLen<float>(tileSn));
        Concat(concatLocal, keysTileFp32, tmpBuf, tileSn / ONE_REPEAT_SORT_NUM);

        LocalTensor<float> sortedTile = sortOutBuf_.Get<float>(GetSortLen<float>(tileSn));
        Sort<float, true>(sortedTile, concatLocal, valsTile, tmpBuf,
                          tileSn / ONE_REPEAT_SORT_NUM);

        LocalTensor<float> outTile = sortOutQ_.AllocTensor<float>();
        LocalTensor<float> sortedKeys = outTile[0];
        LocalTensor<uint32_t> sortedVals = outTile[tileSn].ReinterpretCast<uint32_t>();
        Extract(sortedKeys, sortedVals, sortedTile, tileSn / ONE_REPEAT_SORT_NUM);

        Muls(sortedKeys, sortedKeys, static_cast<float>(-1.0), len);
        LocalTensor<int32_t> keysIntOut = sortedKeys.ReinterpretCast<int32_t>();
        Cast(keysIntOut, sortedKeys, RoundMode::CAST_ROUND, tileSn);
        LocalTensor<int32_t> valsIntOut = sortedVals.ReinterpretCast<int32_t>();

        DataCopyParams cpOutTile;
        cpOutTile.blockCount = 1;
        cpOutTile.blockLen = static_cast<uint32_t>(len * sizeof(int32_t));
        DataCopyPad(wsGm_[wsExpertBase + ti * tileSn], keysIntOut[0], cpOutTile);
        DataCopyPad(wsGm_[wsRowBase + ti * tileSn], valsIntOut[0], cpOutTile);

        sortOutQ_.EnQue<float>(outTile);
        sortInQ_.FreeTensor(inTile);
        LocalTensor<float> outD = sortOutQ_.DeQue<float>();
        sortOutQ_.FreeTensor(outD);
    }

    PipeBarrier<PIPE_ALL>();

    // Phase 2: K-way merge (scalar)
    int64_t ptrs[64], ends[64], rowPtrs[64];
    for (int64_t ti = 0; ti < numTiles; ti++) {
        ptrs[ti] = wsExpertBase + ti * tileSn;
        int64_t tlen = (ti == numTiles - 1) ? (totalFlat - ti * sortNumPerTile) : sortNumPerTile;
        ends[ti] = wsExpertBase + ti * tileSn + tlen;
        rowPtrs[ti] = wsRowBase + ti * tileSn;
    }

    for (int64_t outPos = 0; outPos < totalFlat; outPos++) {
        int32_t minVal = 2147483647;
        int64_t minTile = -1;
        for (int64_t ti = 0; ti < numTiles; ti++) {
            if (ptrs[ti] < ends[ti]) {
                int32_t v = wsGm_.GetValue(ptrs[ti]);
                if (v < minVal) { minVal = v; minTile = ti; }
            }
        }
        if (minTile < 0) break;
        oeGm_.SetValue(outPos, minVal);
        int64_t rowOff = ptrs[minTile] - (wsExpertBase + minTile * tileSn);
        wsGm_.SetValue(wsDstSave + outPos,
            wsGm_.GetValue(rowPtrs[minTile] + rowOff));
        ptrs[minTile]++;
    }

    PipeBarrier<PIPE_ALL>();

    // Phase 3: Post-processing (scatter-invert + gather)
    // Initialize expanded_row_idx to -1
    LocalTensor<int32_t> initBuf = sortInQ_.AllocTensor<int32_t>();
    Duplicate<int32_t>(initBuf, -1, outputNK);
    DataCopyParams cpInit;
    cpInit.blockCount = 1;
    cpInit.blockLen = static_cast<uint32_t>(outputNK * sizeof(int32_t));
    DataCopyPad(orGm_[0], initBuf[0], cpInit);
    sortInQ_.FreeTensor(initBuf);

    // Scatter-invert
    for (int64_t i = 0; i < outputNK; i++) {
        int32_t dstP = wsGm_.GetValue(wsDstSave + i);
        if (dstP >= 0 && dstP < static_cast<int32_t>(totalFlat)) {
            orGm_.SetValue(dstP, static_cast<int32_t>(i));
        }
    }
    PipeBarrier<PIPE_ALL>();

    // Gather x rows
    for (int64_t i = 0; i < outputNK; i++) {
        int32_t srcIdx = wsGm_.GetValue(wsDstSave + i);
        int64_t origRow = srcIdx % N;
        if (origRow < 0) origRow += N;

        LocalTensor<T> xRow = sortInQ_.AllocTensor<T>();
        DataCopyParams cpRow;
        cpRow.blockCount = 1;
        cpRow.blockLen = static_cast<uint32_t>(H * sizeof(T));
        DataCopyPadParams ppRow{false, 0, 0, 0};
        DataCopyPad(xRow[0], xGm_[origRow * H], cpRow, ppRow);
        sortInQ_.EnQue(xRow);
        LocalTensor<T> xRowD = sortInQ_.DeQue<T>();
        DataCopyPad(oxGm_[i * H], xRowD[0], cpRow);
        sortInQ_.FreeTensor(xRowD);
    }
}

// ============================================================================
// Process: entry point
// ============================================================================
template <typename T>
__aicore__ inline void KernelMoeInitRouting<T>::Process()
{
    if (GetBlockIdx() != 0) return;

    if (td_.mode == 0) {
        FullloadSort();
    } else {
        SingleSort();
    }
}

// ============================================================================
// Kernel entry points
// ============================================================================
extern "C" __global__ __aicore__ void moe_init_routing_fp16(
    GM_ADDR x, GM_ADDR r, GM_ADDR e,
    GM_ADDR ox, GM_ADDR oder, GM_ADDR oe,
    GM_ADDR ws, GM_ADDR t)
{
    if (g_coreType == AIC) return;
    AscendC::TPipe pipe;
    KernelMoeInitRouting<half> op;
    op.Init(x, r, e, ox, oder, oe, ws, t, &pipe);
    op.Process();
}

extern "C" __global__ __aicore__ void moe_init_routing_fp32(
    GM_ADDR x, GM_ADDR r, GM_ADDR e,
    GM_ADDR ox, GM_ADDR oder, GM_ADDR oe,
    GM_ADDR ws, GM_ADDR t)
{
