{"content": "/*
 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
 * Licensed under the CANN Open Software License Agreement Version 2.0.
 *
 * MoE Init Routing AscendC kernel.
 * Fuses: stable sort (expert_idx ascending) + scatter-invert + row-gather.
 * Uses UB sort (insertion sort on UB for stability, TILE_ELEM=512 per pass).
 * For N*K > TILE_ELEM: multi-pass sort + K-way merge on GM workspace.
 */

#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t TILE_ELEM = 512;
constexpr int64_t BUFFER_NUM = 2;

struct MoeInitRoutingTiling {
    int32_t N, K, H, totalFlat, outputNK, numTiles, lastTileLen;
};

template <typename T>
class KernelMoeInitRouting {
public:
    __aicore__ inline KernelMoeInitRouting() {}
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR r, GM_ADDR e,
        GM_ADDR ox, GM_ADDR oder, GM_ADDR oe,
        GM_ADDR ws, GM_ADDR t, TPipe* pipeIn);
    __aicore__ inline void Process();

private:
    __aicore__ inline void SortTile(int64_t ti);
    __aicore__ inline void KWayMerge();
    __aicore__ inline void ScatterInvert();
    __aicore__ inline void RowGather();

    TPipe* pipe_;
    MoeInitRoutingTiling td_;

    GlobalTensor<T> xGm_;
    GlobalTensor<int32_t> rGm_;
    GlobalTensor<int32_t> eGm_;
    GlobalTensor<T> oxGm_;
    GlobalTensor<int32_t> orGm_;
    GlobalTensor<int32_t> oeGm_;
    GlobalTensor<int32_t> wsGm_;

    TQue<QuePosition::VECIN, BUFFER_NUM> tileQ_;
    TQue<QuePosition::VECOUT, BUFFER_NUM> rowQ_;
};

template <typename T>
__aicore__ inline void KernelMoeInitRouting<T>::Init(
    GM_ADDR x, GM_ADDR r, GM_ADDR e,
    GM_ADDR ox, GM_ADDR oder, GM_ADDR oe,
    GM_ADDR ws, GM_ADDR t, TPipe* pipeIn)
{
    pipe_ = pipeIn;
    auto* tl = reinterpret_cast<__gm__ MoeInitRoutingTiling*>(t);
    td_.N = static_cast<int32_t>(tl->N);
    td_.K = static_cast<int32_t>(tl->K);
    td_.H = static_cast<int32_t>(tl->H);
    td_.totalFlat = static_cast<int32_t>(tl->totalFlat);
    td_.outputNK = static_cast<int32_t>(tl->outputNK);
    td_.numTiles = static_cast<int32_t>(tl->numTiles);
    td_.lastTileLen = static_cast<int32_t>(tl->lastTileLen);

    xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x), td_.N * td_.H);
    rGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(r), td_.totalFlat);
    eGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(e), td_.totalFlat);
    oxGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(ox), td_.outputNK * td_.H);
    orGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(oder), td_.outputNK);
    oeGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(oe), td_.outputNK);

    int64_t wsSize = td_.numTiles * TILE_ELEM * 2 + td_.totalFlat + 64;
    wsGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(ws), wsSize);

    // Sort tile buffer: (TILE_ELEM * 2 int32) elements for keys+values
    int64_t tileBufSize = TILE_ELEM * 2 * sizeof(int32_t) + 256;
    pipe_->InitBuffer(tileQ_, BUFFER_NUM, tileBufSize);

    // Row gather buffer: H elements of type T + padding
    int64_t rowBufSize = td_.H * sizeof(T) + 4096;
    pipe_->InitBuffer(rowQ_, BUFFER_NUM, rowBufSize);
}

// ============================================================================
// SortTile: load and sort one tile of expert+row pairs by expert (ascending)
// Uses insertion sort on UB for stability
// ============================================================================
template <typename T>
__aicore__ inline void KernelMoeInitRouting<T>::SortTile(int64_t ti)
{
    int64_t start = ti * TILE_ELEM;
    int64_t len = (ti == td_.numTiles - 1) ? td_.lastTileLen : TILE_ELEM;
    if (len <= 0) return;

    int64_t K = td_.K;
    int64_t wsExpertBase = td_.numTiles * TILE_ELEM;

    LocalTensor<int32_t> buf = tileQ_.AllocTensor<int32_t>();

    // Load expert+row data from 2D [N,K] flatten view
    // For each element j in tile: load expert at flat index, row at companion offset
    for (int64_t j = 0; j < len; j++) {
        int64_t p = start + j;
        int64_t r = p / K;
        int64_t c = p % K;
        buf.SetValue(j, eGm_.GetValue(r * K + c));
        buf.SetValue(TILE_ELEM + j, rGm_.GetValue(r * K + c));
    }

    // Insertion sort by expert value (ascending, stable)
    for (int64_t i = 1; i < static_cast<int64_t>(len); i++) {
        int32_t keyE = buf.GetValue(i);
        int32_t keyR = buf.GetValue(TILE_ELEM + i);
        int64_t jj = i - 1;
        while (jj >= 0) {
            int32_t v = buf.GetValue(jj);
            if (v <= keyE) break;
            buf.SetValue(jj + 1, v);
            buf.SetValue(TILE_ELEM + jj + 1, buf.GetValue(TILE_ELEM + jj));
            jj--;
        }
        buf.SetValue(jj + 1, keyE);
        buf.SetValue(TILE_ELEM + jj + 1, keyR);
    }

    // Write sorted tile to workspace: expert at upper half, row at lower half
    for (int64_t j = 0; j < len; j++) {
        wsGm_.SetValue(wsExpertBase + ti * TILE_ELEM + j, buf.GetValue(j));
        wsGm_.SetValue(ti * TILE_ELEM + j, buf.GetValue(TILE_ELEM + j));
    }

    tileQ_.FreeTensor(buf);
}

// ============================================================================
// KWayMerge: merge sorted tiles into final sorted output
// ============================================================================
template <typename T>
__aicore__ inline void KernelMoeInitRouting<T>::KWayMerge()
{
    int64_t totalFlat = td_.totalFlat;
    int64_t numTiles = td_.numTiles;
    int64_t wsExpertBase = numTiles * TILE_ELEM;
    int64_t wsDstSave = wsExpertBase + numTiles * TILE_ELEM;

    if (numTiles <= 1) {
        // Single tile: just copy
        for (int64_t j = 0; j < totalFlat; j++) {
            oeGm_.SetValue(j, wsGm_.GetValue(wsExpertBase + j));
            wsGm_.SetValue(wsDstSave + j, wsGm_.GetValue(j));
        }
        return;
    }

    // K-way merge: track position in each sorted tile
    int64_t ptrs[64], ends[64];
    for (int64_t ti = 0; ti < numTiles; ti++) {
        ptrs[ti] = wsExpertBase + ti * TILE_ELEM;
        int64_t tlen = (ti == numTiles - 1) ? td_.lastTileLen : TILE_ELEM;
        ends[ti] = wsExpertBase + ti * TILE_ELEM + tlen;
    }

    for (int64_t outPos = 0; outPos < totalFlat; outPos++) {
        int32_t minVal = 2147483647;
        int64_t minTile = -1;
        for (int64_t ti = 0; ti < numTiles; ti++) {
            if (ptrs[ti] < ends[ti]) {
                int32_t v = wsGm_.GetValue(ptrs[ti]);
                if (v < minVal) { minVal = v; minTile = ti; }
            }
        }
        if (minTile < 0) break;

        oeGm_.SetValue(outPos, minVal);
        int64_t rowOff = ptrs[minTile] - (wsExpertBase + minTile * TILE_ELEM);
        wsGm_.SetValue(wsDstSave + outPos,
            wsGm_.GetValue(minTile * TILE_ELEM + rowOff));
        ptrs[minTile]++;
    }
}

// ============================================================================
// ScatterInvert: src_to_dst[dst_to_src[i]] = i
// ============================================================================
template <typename T>
__aicore__ inline void KernelMoeInitRouting<T>::ScatterInvert()
{
    int64_t totalFlat = td_.totalFlat;
    int64_t outputNK = td_.outputNK;
    int64_t numTiles = td_.numTiles;
    int64_t wsExpertBase = numTiles * TILE_ELEM;
    int64_t wsDstSave = wsExpertBase + numTiles * TILE_ELEM;

    // Initialize orGm_ to -1
    LocalTensor<int32_t> initBuf = tileQ_.AllocTensor<int32_t>();
    int64_t done = 0;
    while (done < outputNK) {
        int64_t cur = (outputNK - done > TILE_ELEM) ? TILE_ELEM : (outputNK - done);
        Duplicate<int32_t>(initBuf, -1, cur);
        DataCopyParams cpInit;
        cpInit.blockCount = 1;
        cpInit.blockLen = static_cast<uint32_t>(cur * sizeof(int32_t));
        DataCopyPad(orGm_[done], initBuf[0], cpInit);
        done += cur;
    }
    tileQ_.FreeTensor(initBuf);

    // Scatter: orGm_[dst_to_src[i]] = i
    for (int64_t i = 0; i < outputNK; i++) {
        int32_t dstP = wsGm_.GetValue(wsDstSave + i);
        if (dstP >= 0 && dstP < static_cast<int32_t>(totalFlat)) {
            orGm_.SetValue(dstP, static_cast<int32_t>(i));
        }
    }
}

// ============================================================================
// RowGather: expanded_x[p, :] = x[dst_to_src[p] % N, :]
// ============================================================================
template <typename T>
__aicore__ inline void KernelMoeInitRouting<T>::RowGather()
{
    int64_t outputNK = td_.outputNK;
    int64_t H = td_.H;
    int64_t N = td_.N;
    int64_t numTiles = td_.numTiles;
    int64_t wsExpertBase = numTiles * TILE_ELEM;
    int64_t wsDstSave = wsExpertBase + numTiles * TILE_ELEM;

    for (int64_t i = 0; i < outputNK; i++) {
        int32_t srcIdx = wsGm_.GetValue(wsDstSave + i);
        int64_t origRow = srcIdx % N;
        if (origRow < 0) origRow += N;

        // Copy row from x to ox using DataCopyPad
        LocalTensor<T> xRow = rowQ_.AllocTensor<T>();
        DataCopyParams cpRow;
        cpRow.blockCount = 1;
        cpRow.blockLen = static_cast<uint32_t>(H * sizeof(T));
        DataCopyPadParams ppRow{false, 0, 0, 0};
        DataCopyPad(xRow[0], xGm_[origRow * H], cpRow, ppRow);
        rowQ_.EnQue(xRow);
        LocalTensor<T> xRowD = rowQ_.DeQue<T>();
        DataCopyPad(oxGm_[i * H], xRowD[0], cpRow);
        rowQ_.FreeTensor(xRowD);
    }
}

// ============================================================================
// Process: main entry point
// ============================================================================
template <typename T>
__aicore__ inline void KernelMoeInitRouting<T>::Process()
{
    if (GetBlockIdx() != 0) return;

    // Phase 1: Per-tile UB sort
    for (int64_t ti = 0; ti < td_.numTiles; ti++) {
        SortTile(ti);
    }
    PipeBarrier<PIPE_ALL>();

    // Phase 2: K-way merge to output sorted experts + workspace dst_to_src
    KWayMerge();
    PipeBarrier<PIPE_ALL>();

    // Phase 3: Scatter-invert mapping
    ScatterInvert();
    PipeBarrier<PIPE_ALL>();

    // Phase 4: Row gather
    RowGather();
}

// ============================================================================
// Kernel entry points
// ============================================================================
extern "C" __global__ __aicore__ void moe_init_routing_fp16(
    GM_ADDR x, GM_ADDR r, GM_ADDR e,
    GM_ADDR ox, GM_ADDR oder, GM_ADDR oe,
    GM_ADDR ws, GM_ADDR t)
{
    if (g_coreType == AIC) return;
    AscendC::TPipe pipe;
    KernelMoeInitRouting<half> op;
    op.Init(x, r, e, ox, oder, oe, ws, t, &pipe);
    op.Process();
}

extern "C" __global__ __aicore__ void moe_init_routing_fp32(
    GM_ADDR x, GM_ADDR r, GM_ADDR e,
    GM_ADDR ox, GM_ADDR oder, GM_ADDR oe,
    GM_ADDR ws, GM_ADDR t)
{
    if (g_coreType == AIC) return;
    AscendC::TPipe pipe;
    KernelMoeInitRouting<float> op;
    op.Init(x, r, e, ox, oder, oe, ws, t, &pipe);
    op.Process();
}

extern "C" __global__ __aicore__ void moe_init_routing_bf16(
    GM_ADDR x, GM_ADDR r, GM_ADDR e,
    GM_ADDR ox, GM_ADDR oder, GM_ADDR oe,
    GM_ADDR ws, GM_ADDR t)
{
    if (g_coreType == AIC) return;
    AscendC::TPipe pipe;
    KernelMoeInitRouting<bfloat16_t> op;
    op.Init(x, r, e, ox, oder, oe, ws, t, &pipe);
    op.Process();
}
