{"content": "/*
 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
 * Licensed under the CANN Open Software License Agreement Version 2.0.
 *
 * MoE Init Routing AscendC kernel.
 * Fuses: stable sort + scatter-invert + row-gather.
 * Key design: ALL GM↔UB transfers use DataCopyPad + EnQue/DeQue.
 * No direct GlobalTensor::GetValue/SetValue for writes.
 */

#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t TILE_ELEM = 512;
constexpr int64_t BUFFER_NUM = 2;

struct MoeInitRoutingTiling {
    int32_t N, K, H, totalFlat, outputNK, numTiles, lastTileLen;
};

template <typename T>
class KernelMoeInitRouting {
public:
    __aicore__ inline KernelMoeInitRouting() {}
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR r, GM_ADDR e,
        GM_ADDR ox, GM_ADDR oder, GM_ADDR oe,
        GM_ADDR ws, GM_ADDR t, TPipe* pipeIn);
    __aicore__ inline void Process();

private:
    __aicore__ inline void SortTile(int64_t ti);
    __aicore__ inline void WriteOutputs();

    TPipe* pipe_;
    MoeInitRoutingTiling td_;

    GlobalTensor<T> xGm_;
    GlobalTensor<int32_t> rGm_;
    GlobalTensor<int32_t> eGm_;
    GlobalTensor<T> oxGm_;
    GlobalTensor<int32_t> orGm_;
    GlobalTensor<int32_t> oeGm_;
    GlobalTensor<int32_t> wsGm_;

    TQue<QuePosition::VECIN, BUFFER_NUM> qIn_;
    TQue<QuePosition::VECOUT, BUFFER_NUM> qOut_;
};

template <typename T>
__aicore__ inline void KernelMoeInitRouting<T>::Init(
    GM_ADDR x, GM_ADDR r, GM_ADDR e,
    GM_ADDR ox, GM_ADDR oder, GM_ADDR oe,
    GM_ADDR ws, GM_ADDR t, TPipe* pipeIn)
{
    pipe_ = pipeIn;
    auto* tl = reinterpret_cast<__gm__ MoeInitRoutingTiling*>(t);
    td_.N = tl->N;
    td_.K = tl->K;
    td_.H = tl->H;
    td_.totalFlat = tl->totalFlat;
    td_.outputNK = tl->outputNK;
    td_.numTiles = tl->numTiles;
    td_.lastTileLen = tl->lastTileLen;

    xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x), td_.N * td_.H);
    rGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(r), td_.totalFlat);
    eGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(e), td_.totalFlat);
    oxGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(ox), td_.outputNK * td_.H);
    orGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(oder), td_.outputNK);
    oeGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(oe), td_.outputNK);

    int64_t wsSize = td_.totalFlat * 2 + 64;
    wsGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(ws), wsSize);

    int64_t bufSize = TILE_ELEM * 2 * sizeof(int32_t) + 256;
    pipe_->InitBuffer(qIn_,  BUFFER_NUM, bufSize);
    pipe_->InitBuffer(qOut_, BUFFER_NUM, bufSize);
}

// ============================================================================
// SortTile: load tile from GM (2D→1D), sort on UB, write to workspace
// All GM↔UB via DataCopyPad + EnQue/DeQue
// ============================================================================
template <typename T>
__aicore__ inline void KernelMoeInitRouting<T>::SortTile(int64_t ti)
{
    int64_t start = ti * TILE_ELEM;
    int64_t len = (ti == td_.numTiles - 1) ? td_.lastTileLen : TILE_ELEM;
    if (len <= 0) return;

    int64_t K = td_.K;
    int64_t totalFlat = td_.totalFlat;

    // Step 1: Load expert data from GM as flat 1D
    // expert_idx is [N,K] int32, row-major contiguous
    // Reading [start, start+len) from contiguous storage
    LocalTensor<int32_t> buf = qIn_.AllocTensor<int32_t>();
    DataCopyParams cp;
    cp.blockCount = 1;
    cp.blockLen = static_cast<uint32_t>(len * sizeof(int32_t));
    DataCopyPadParams pp{false, 0, 0, 0};
    DataCopyPad(buf[0], eGm_[start], cp, pp);
    qIn_.EnQue(buf);
    LocalTensor<int32_t> inDeq = qIn_.DeQue<int32_t>();

    // Step 2: Load row_idx data from GM
    LocalTensor<int32_t> buf2 = qIn_.AllocTensor<int32_t>();
    DataCopyPad(buf2[0], rGm_[start], cp, pp);
    qIn_.EnQue(buf2);
    LocalTensor<int32_t> rowDeq = qIn_.DeQue<int32_t>();

    // Step 3: Merge expert+row into paired buffer for sorting
    // Use a single buffer: [0..len-1] = expert, [TILE_ELEM..TILE_ELEM+len-1] = row
    LocalTensor<int32_t> sortBuf = qIn_.AllocTensor<int32_t>();
    for (int64_t j = 0; j < len; j++) {
        sortBuf.SetValue(j, inDeq.GetValue(j));
        sortBuf.SetValue(TILE_ELEM + j, rowDeq.GetValue(j));
    }
    qIn_.FreeTensor(inDeq);
    qIn_.FreeTensor(rowDeq);

    // Step 4: Insertion sort by expert value (ascending, stable)
    for (int64_t i = 1; i < len; i++) {
        int32_t keyE = sortBuf.GetValue(i);
        int32_t keyR = sortBuf.GetValue(TILE_ELEM + i);
        int64_t jj = i - 1;
        while (jj >= 0) {
            int32_t v = sortBuf.GetValue(jj);
            if (v <= keyE) break;
            sortBuf.SetValue(jj + 1, v);
            sortBuf.SetValue(TILE_ELEM + jj + 1, sortBuf.GetValue(TILE_ELEM + jj));
            jj--;
        }
        sortBuf.SetValue(jj + 1, keyE);
        sortBuf.SetValue(TILE_ELEM + jj + 1, keyR);
    }

    // Step 5: Write sorted data to workspace via EnQue→DeQue→DataCopyPad
    // Write sorted expert keys
    qIn_.EnQue(sortBuf);
    LocalTensor<int32_t> outDeq = qIn_.DeQue<int32_t>();
    DataCopyPad(wsGm_[ti * TILE_ELEM], outDeq[0], cp);
    qIn_.FreeTensor(outDeq);

    // Write sorted row values
    LocalTensor<int32_t> outBuf = qIn_.AllocTensor<int32_t>();
    for (int64_t j = 0; j < len; j++) {
        outBuf.SetValue(j, sortBuf.GetValue(TILE_ELEM + j));
    }
    qIn_.EnQue(outBuf);
    LocalTensor<int32_t> outDeq2 = qIn_.DeQue<int32_t>();
    DataCopyPad(wsGm_[totalFlat + ti * TILE_ELEM], outDeq2[0], cp);
    qIn_.FreeTensor(outDeq2);
    qIn_.FreeTensor(sortBuf);
}

// ============================================================================
// WriteOutputs: K-way merge sorted tiles → outputs + scatter-invert + row-gather
// All GM outputs written via EnQue→DeQue→DataCopyPad
// ============================================================================
template <typename T>
__aicore__ inline void KernelMoeInitRouting<T>::WriteOutputs()
{
    int64_t totalFlat = td_.totalFlat;
    int64_t outputNK = td_.outputNK;
    int64_t N = td_.N;
    int64_t H = td_.H;
    int64_t numTiles = td_.numTiles;

    // Load all sorted tiles into UB for merge
    // For numTiles == 1, just copy directly
    // For numTiles > 1, do K-way merge on UB

    if (numTiles == 1) {
        int64_t len = td_.lastTileLen;
        DataCopyParams cp;
        cp.blockCount = 1;
        cp.blockLen = static_cast<uint32_t>(len * sizeof(int32_t));
        DataCopyPadParams pp{false, 0, 0, 0};

        // Load sorted experts
        LocalTensor<int32_t> expBuf = qIn_.AllocTensor<int32_t>();
        DataCopyPad(expBuf[0], wsGm_[0], cp, pp);
        qIn_.EnQue(expBuf);
        LocalTensor<int32_t> expDeq = qIn_.DeQue<int32_t>();

        // Load sorted rows
        LocalTensor<int32_t> rowBuf = qIn_.AllocTensor<int32_t>();
        DataCopyPad(rowBuf[0], wsGm_[totalFlat], cp, pp);
        qIn_.EnQue(rowBuf);
        LocalTensor<int32_t> rowDeq = qIn_.DeQue<int32_t>();

        // ---- Write expanded_expert_idx ----
        LocalTensor<int32_t> outExpert = qOut_.AllocTensor<int32_t>();
        for (int64_t j = 0; j < outputNK; j++) {
            outExpert.SetValue(j, expDeq.GetValue(j));
        }
        qOut_.EnQue(outExpert);
        LocalTensor<int32_t> outExpD = qOut_.DeQue<int32_t>();
        DataCopyPad(oeGm_[0], outExpD[0], cp);
        qOut_.FreeTensor(outExpD);

        // ---- Compute expanded_row_idx (scatter-invert on UB) ----
        // dst_to_src = rowDeq[0..outputNK-1]
        // expanded_row_idx = invert: orGm_[dst_to_src[i]] = i
        // But we can't directly write to GM with SetValue
        // Instead: build expanded_row_idx on UB, then DataCopyPad to GM

        // Initialize UB output to -1
        LocalTensor<int32_t> outRow = qOut_.AllocTensor<int32_t>();
        Duplicate<int32_t>(outRow, -1, outputNK);

        // Scatter: outRow[dst_to_src[i]] = i
        for (int64_t i = 0; i < outputNK; i++) {
            int32_t dstP = rowDeq.GetValue(i);
            if (dstP >= 0 && dstP < static_cast<int32_t>(totalFlat)) {
                outRow.SetValue(dstP, static_cast<int32_t>(i));
            }
        }
        qOut_.EnQue(outRow);
        LocalTensor<int32_t> outRowD = qOut_.DeQue<int32_t>();
        DataCopyPad(orGm_[0], outRowD[0], cp);
        qOut_.FreeTensor(outRowD);

        // ---- Compute expanded_x (row gather) ----
        // For each p in [0, outputNK):
        //   origRow = rowDeq[p] % N
        //   copy x[origRow, :] to ox[p, :]
        for (int64_t p = 0; p < outputNK; p++) {
            int32_t srcIdx = rowDeq.GetValue(p);
            int64_t origRow = srcIdx % N;
            if (origRow < 0) origRow += N;

            // GM→UB: load x row
            LocalTensor<T> xRowL = qIn_.AllocTensor<T>();
            DataCopyParams cpRow;
            cpRow.blockCount = 1;
            cpRow.blockLen = static_cast<uint32_t>(H * sizeof(T));
            DataCopyPadParams ppRow{false, 0, 0, 0};
            DataCopyPad(xRowL[0], xGm_[origRow * H], cpRow, ppRow);
            qIn_.EnQue(xRowL);
            LocalTensor<T> xRowD = qIn_.DeQue<T>();
            // UB→GM: write to ox
            DataCopyPad(oxGm_[p * H], xRowD[0], cpRow);
            qIn_.FreeTensor(xRowD);
        }

        qIn_.FreeTensor(expDeq);
        qIn_.FreeTensor(rowDeq);
    } else {
        // Multi-tile case: K-way merge
        // Load sorted tiles, merge, then do same post-processing
        // For simplicity and correctness, process in UB-sized batches

        int64_t ks[64];   // current index within each tile's sorted data
        int64_t eq[64];   // how many elements consumed from each tile
        int64_t tlen[64]; // total elements in each tile
        for (int64_t ti = 0; ti < numTiles; ti++) {
            ks[ti] = 0;
            eq[ti] = 0;
            tlen[ti] = (ti == numTiles - 1) ? td_.lastTileLen : TILE_ELEM;
        }

        // Load all tile data into UB - but we can't fit everything
        // Load per batch of TILE_ELEM elements (expert or row at a time)

        // Phase A: Build merged expert and row output
        // Use windows: load a window of each tile's expert data, compare

        DataCopyParams cp;
        cp.blockCount = 1;
        cp.blockLen = static_cast<uint32_t>(TILE_ELEM * sizeof(int32_t));
        DataCopyPadParams pp{false, 0, 0, 0};

        // Allocate UB buffers for K windows
        LocalTensor<int32_t> win[64];
        LocalTensor<int32_t> winRow[64];
        for (int64_t ti = 0; ti < numTiles; ti++) {
            win[ti] = qIn_.AllocTensor<int32_t>();
            DataCopyPad(win[ti][0], wsGm_[ti * TILE_ELEM], cp, pp);
            qIn_.EnQue(win[ti]);
        }
        for (int64_t ti = 0; ti < numTiles; ti++) {
            win[ti] = qIn_.DeQue<int32_t>();
        }

        // Load row windows
        for (int64_t ti = 0; ti < numTiles; ti++) {
            winRow[ti] = qIn_.AllocTensor<int32_t>();
            DataCopyPad(winRow[ti][0], wsGm_[totalFlat + ti * TILE_ELEM], cp, pp);
            qIn_.EnQue(winRow[ti]);
        }
        for (int64_t ti = 0; ti < numTiles; ti++) {
            winRow[ti] = qIn_.DeQue<int32_t>();
        }

        // Merge into UB output buffers
        LocalTensor<int32_t> mergedExp = qOut_.AllocTensor<int32_t>();
        LocalTensor<int32_t> mergedRow = qOut_.AllocTensor<int32_t>();

        for (int64_t outPos = 0; outPos < totalFlat; outPos++) {
            int32_t minVal = 2147483647;
            int64_t minTile = -1;
            for (int64_t ti = 0; ti < numTiles; ti++) {
                if (eq[ti] < tlen[ti]) {
                    int32_t v = win[ti].GetValue(eq[ti]);
                    if (v < minVal) { minVal = v; minTile = ti; }
                }
            }
            mergedExp.SetValue(outPos, minVal);
            mergedRow.SetValue(outPos, winRow[minTile].GetValue(eq[minTile]));
            eq[minTile]++;
        }

        // Write expanded_expert_idx to GM
        qOut_.EnQue(mergedExp);
        LocalTensor<int32_t> expOut = qOut_.DeQue<int32_t>();
        cp.blockLen = static_cast<uint32_t>(outputNK * sizeof(int32_t));
        DataCopyPad(oeGm_[0], expOut[0], cp);
        qOut_.FreeTensor(expOut);

        // Free window buffers
        for (int64_t ti = 0; ti < numTiles; ti++) {
            qIn_.FreeTensor(win[ti]);
            qIn_.FreeTensor(winRow[ti]);
        }

        // Scatter-invert on UB
        LocalTensor<int32_t> scatterOut = qOut_.AllocTensor<int32_t>();
        Duplicate<int32_t>(scatterOut, -1, outputNK);
        for (int64_t i = 0; i < outputNK; i++) {
            int32_t dstP = mergedRow.GetValue(i);
            if (dstP >= 0 && dstP < static_cast<int32_t>(totalFlat)) {
                scatterOut.SetValue(dstP, static_cast<int32_t>(i));
            }
        }
        qOut_.EnQue(scatterOut);
        LocalTensor<int32_t> scOutD = qOut_.DeQue<int32_t>();
        DataCopyPad(orGm_[0], scOutD[0], cp);
        qOut_.FreeTensor(scOutD);

        // Row gather
        for (int64_t p = 0; p < outputNK; p++) {
            int32_t srcIdx = mergedRow.GetValue(p);
            int64_t origRow = srcIdx % N;
            if (origRow < 0) origRow += N;

            LocalTensor<T> xRowL = qIn_.AllocTensor<T>();
            DataCopyParams cpRow;
            cpRow.blockCount = 1;
            cpRow.blockLen = static_cast<uint32_t>(H * sizeof(T));
            DataCopyPadParams ppRow{false, 0, 0, 0};
            DataCopyPad(xRowL[0], xGm_[origRow * H], cpRow, ppRow);
            qIn_.EnQue(xRowL);
            LocalTensor<T> xRowD = qIn_.DeQue<T>();
            DataCopyPad(oxGm_[p * H], xRowD[0], cpRow);
            qIn_.FreeTensor(xRowD);
        }

        qIn_.FreeTensor(mergedRow);
    }
}

// ============================================================================
// Process
// ============================================================================
template <typename T>
__aicore__ inline void KernelMoeInitRouting<T>::Process()
{
    if (GetBlockIdx() != 0) return;

    // Phase 1: Per-tile UB sort, write to workspace
    for (int64_t ti = 0; ti < td_.numTiles; ti++) {
        SortTile(ti);
    }
    PipeBarrier<PIPE_ALL>();

    // Phase 2: Merge + invert + gather, write all outputs
    WriteOutputs();
}

