{"content": "/*
 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
 * Licensed under the CANN Open Software License Agreement Version 2.0.
 *
 * MoE Init Routing AscendC kernel.
 * Fuses: stable sort + scatter-invert + row-gather.
 * GM→UB: VECIN queue (CopyIn pattern with EnQue/DeQue)
 * UB→GM: VECOUT queue (CopyOut pattern with EnQue/DeQue)
 * Compute-only temp: TBuf (VecCalc, no EnQue/DeQue needed)
 */

#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t TILE_ELEM = 256;
constexpr int64_t BUFFER_NUM = 2;

struct MoeInitRoutingTiling {
    int32_t N, K, H, totalFlat, outputNK, numTiles, lastTileLen;
};

template <typename T>
class KernelMoeInitRouting {
public:
    __aicore__ inline KernelMoeInitRouting() {}
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR r, GM_ADDR e,
        GM_ADDR ox, GM_ADDR oder, GM_ADDR oe,
        GM_ADDR ws, GM_ADDR t, TPipe* pipeIn);
    __aicore__ inline void Process();

private:
    __aicore__ inline void SortOneTile(int64_t ti);
    __aicore__ inline void MergeAndOutput();

    TPipe* pipe_;
    MoeInitRoutingTiling td_;

    GlobalTensor<T> xGm_;
    GlobalTensor<int32_t> rGm_;
    GlobalTensor<int32_t> eGm_;
    GlobalTensor<T> oxGm_;
    GlobalTensor<int32_t> orGm_;
    GlobalTensor<int32_t> oeGm_;
    GlobalTensor<int32_t> wsGm_;

    TQue<QuePosition::VECIN, BUFFER_NUM> inQ_;
    TQue<QuePosition::VECOUT, BUFFER_NUM> outQ_;
    TBuf<TPosition::VECCALC> calcBuf_;
};

template <typename T>
__aicore__ inline void KernelMoeInitRouting<T>::Init(
    GM_ADDR x, GM_ADDR r, GM_ADDR e,
    GM_ADDR ox, GM_ADDR oder, GM_ADDR oe,
    GM_ADDR ws, GM_ADDR t, TPipe* pipeIn)
{
    pipe_ = pipeIn;
    auto* tl = reinterpret_cast<__gm__ MoeInitRoutingTiling*>(t);
    td_.N = tl->N;
    td_.K = tl->K;
    td_.H = tl->H;
    td_.totalFlat = tl->totalFlat;
    td_.outputNK = tl->outputNK;
    td_.numTiles = tl->numTiles;
    td_.lastTileLen = tl->lastTileLen;

    xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x), td_.N * td_.H);
    rGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(r), td_.totalFlat);
    eGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(e), td_.totalFlat);
    oxGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(ox), td_.outputNK * td_.H);
    orGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(oder), td_.outputNK);
    oeGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(oe), td_.outputNK);

    int64_t wsSize = (td_.numTiles * TILE_ELEM) * 2 + td_.totalFlat + 64;
    wsGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(ws), wsSize);

    int64_t bufSize = TILE_ELEM * 2 * sizeof(int32_t) + 256;
    pipe_->InitBuffer(inQ_,  BUFFER_NUM, bufSize);
    pipe_->InitBuffer(outQ_, BUFFER_NUM, bufSize);
    pipe_->InitBuffer(calcBuf_, bufSize);
}

// ============================================================================
// SortOneTile: CopyIn tile → sort on UB (TBuf) → CopyOut to workspace
// ============================================================================
template <typename T>
__aicore__ inline void KernelMoeInitRouting<T>::SortOneTile(int64_t ti)
{
    int64_t start = ti * TILE_ELEM;
    int64_t len = (ti == td_.numTiles - 1) ? td_.lastTileLen : TILE_ELEM;
    if (len <= 0) return;

    int64_t totalFlat = td_.totalFlat;

    // ---- CopyIn: load expert and row data from GM ----
    LocalTensor<int32_t> inL = inQ_.AllocTensor<int32_t>();
    DataCopyParams cp;
    cp.blockCount = 1;
    cp.blockLen = static_cast<uint32_t>(len * sizeof(int32_t));
    DataCopyPadParams pp{false, 0, 0, 0};

    // Load expert keys (NOTE: eGm_ is 1D flat, start is element offset)
    DataCopyPad(inL[0], eGm_[start], cp, pp);
    inQ_.EnQue(inL);
    LocalTensor<int32_t> expIn = inQ_.DeQue<int32_t>();

    // Load row indices
    LocalTensor<int32_t> rowL = inQ_.AllocTensor<int32_t>();
    DataCopyPad(rowL[0], rGm_[start], cp, pp);
    inQ_.EnQue(rowL);
    LocalTensor<int32_t> rowIn = inQ_.DeQue<int32_t>();

    // ---- Sort: copy to calcBuf, insertion sort on expert keys ----
    LocalTensor<int32_t> sortB = calcBuf_.Get<int32_t>(TILE_ELEM * 2 * sizeof(int32_t));
    for (int64_t j = 0; j < len; j++) {
        sortB.SetValue(j, expIn.GetValue(j));
        sortB.SetValue(TILE_ELEM + j, rowIn.GetValue(j));
    }

    // Insertion sort by expert key ascending (stable)
    for (int64_t i = 1; i < len; i++) {
        int32_t keyE = sortB.GetValue(i);
        int32_t keyR = sortB.GetValue(TILE_ELEM + i);
        int64_t jj = i - 1;
        while (jj >= 0 && sortB.GetValue(jj) > keyE) {
            sortB.SetValue(jj + 1, sortB.GetValue(jj));
            sortB.SetValue(TILE_ELEM + jj + 1, sortB.GetValue(TILE_ELEM + jj));
            jj--;
        }
        sortB.SetValue(jj + 1, keyE);
        sortB.SetValue(TILE_ELEM + jj + 1, keyR);
    }

    // ---- CopyOut: write sorted experts and rows to workspace ----
    // Expert keys to ws[ti * TILE_ELEM ...]
    LocalTensor<int32_t> outE = outQ_.AllocTensor<int32_t>();
    for (int64_t j = 0; j < len; j++) {
        outE.SetValue(j, sortB.GetValue(j));
    }
    outQ_.EnQue(outE);
    LocalTensor<int32_t> outEDq = outQ_.DeQue<int32_t>();
    DataCopyPad(wsGm_[ti * TILE_ELEM], outEDq[0], cp);
    outQ_.FreeTensor(outEDq);

    // Row values to ws[totalFlat + ti * TILE_ELEM ...]
    LocalTensor<int32_t> outR = outQ_.AllocTensor<int32_t>();
    for (int64_t j = 0; j < len; j++) {
        outR.SetValue(j, sortB.GetValue(TILE_ELEM + j));
    }
    outQ_.EnQue(outR);
    LocalTensor<int32_t> outRDq = outQ_.DeQue<int32_t>();
    DataCopyPad(wsGm_[totalFlat + ti * TILE_ELEM], outRDq[0], cp);
    outQ_.FreeTensor(outRDq);

    inQ_.FreeTensor(expIn);
    inQ_.FreeTensor(rowIn);
}

// ============================================================================
// MergeAndOutput: merge sorted tiles, do scatter-invert + row-gather
// ============================================================================
template <typename T>
__aicore__ inline void KernelMoeInitRouting<T>::MergeAndOutput()
{
    int64_t totalFlat = td_.totalFlat;
    int64_t outputNK = td_.outputNK;
    int64_t N = td_.N;
    int64_t H = td_.H;
    int64_t numTiles = td_.numTiles;

    if (numTiles == 1) {
        int64_t len = td_.lastTileLen;
        DataCopyParams cp;
        cp.blockCount = 1;
        cp.blockLen = static_cast<uint32_t>(len * sizeof(int32_t));
        DataCopyPadParams pp{false, 0, 0, 0};

        // CopyIn sorted experts
        LocalTensor<int32_t> eIn = inQ_.AllocTensor<int32_t>();
        DataCopyPad(eIn[0], wsGm_[0], cp, pp);
        inQ_.EnQue(eIn);
        LocalTensor<int32_t> eInD = inQ_.DeQue<int32_t>();

        // CopyIn sorted rows
        LocalTensor<int32_t> rIn = inQ_.AllocTensor<int32_t>();
        DataCopyPad(rIn[0], wsGm_[totalFlat], cp, pp);
        inQ_.EnQue(rIn);
        LocalTensor<int32_t> rInD = inQ_.DeQue<int32_t>();

        // ---- Output 1: expanded_expert_idx ----
        LocalTensor<int32_t> oeOut = outQ_.AllocTensor<int32_t>();
        for (int64_t j = 0; j < outputNK; j++) {
            oeOut.SetValue(j, eInD.GetValue(j));
        }
        outQ_.EnQue(oeOut);
        LocalTensor<int32_t> oeDq = outQ_.DeQue<int32_t>();
        cp.blockLen = static_cast<uint32_t>(outputNK * sizeof(int32_t));
        DataCopyPad(oeGm_[0], oeDq[0], cp);
        outQ_.FreeTensor(oeDq);

        // ---- Output 2: expanded_row_idx (scatter-invert) ----
        // Initialize to -1 on UB
        LocalTensor<int32_t> orOut = outQ_.AllocTensor<int32_t>();
        Duplicate<int32_t>(orOut, -1, outputNK);
        // Scatter: orOut[dst_to_src[i]] = i
        for (int64_t i = 0; i < outputNK; i++) {
            int32_t dstP = rInD.GetValue(i);
            if (dstP >= 0 && dstP < static_cast<int32_t>(totalFlat)) {
                orOut.SetValue(dstP, static_cast<int32_t>(i));
            }
        }
        outQ_.EnQue(orOut);
        LocalTensor<int32_t> orDq = outQ_.DeQue<int32_t>();
        DataCopyPad(orGm_[0], orDq[0], cp);
        outQ_.FreeTensor(orDq);

        // ---- Output 3: expanded_x (row gather) ----
        for (int64_t p = 0; p < outputNK; p++) {
            int32_t srcIdx = rInD.GetValue(p);
            int64_t origRow = srcIdx % N;
            if (origRow < 0) origRow += N;

            LocalTensor<T> xRowL = inQ_.AllocTensor<T>();
            DataCopyParams cpRow;
            cpRow.blockCount = 1;
            cpRow.blockLen = static_cast<uint32_t>(H * sizeof(T));
            DataCopyPadParams ppRow{false, 0, 0, 0};
            DataCopyPad(xRowL[0], xGm_[origRow * H], cpRow, ppRow);
            inQ_.EnQue(xRowL);
            LocalTensor<T> xRowD = inQ_.DeQue<T>();
            DataCopyPad(oxGm_[p * H], xRowD[0], cpRow);
            inQ_.FreeTensor(xRowD);
        }

        inQ_.FreeTensor(eInD);
        inQ_.FreeTensor(rInD);
    } else {
        // Multi-tile: merge via workspaces
        // Load all tiles in chunks and merge
        DataCopyParams cp;
        cp.blockCount = 1;
        DataCopyPadParams pp{false, 0, 0, 0};

        int64_t tlen[64];
        for (int64_t ti = 0; ti < numTiles; ti++) {
            tlen[ti] = (ti == numTiles - 1) ? td_.lastTileLen : TILE_ELEM;
        }

        // Load all sorted data into UB (for numTiles up to ~8, TILE_ELEM=256, fits in UB)
        // For larger numTiles, process in batches
        LocalTensor<int32_t> allExp = inQ_.AllocTensor<int32_t>();
        for (int64_t ti = 0; ti < numTiles; ti++) {
            cp.blockLen = static_cast<uint32_t>(tlen[ti] * sizeof(int32_t));
            DataCopyPad(allExp[ti * TILE_ELEM], wsGm_[ti * TILE_ELEM], cp, pp);
        }
        inQ_.EnQue(allExp);
        LocalTensor<int32_t> allExpD = inQ_.DeQue<int32_t>();

        LocalTensor<int32_t> allRow = inQ_.AllocTensor<int32_t>();
        for (int64_t ti = 0; ti < numTiles; ti++) {
            cp.blockLen = static_cast<uint32_t>(tlen[ti] * sizeof(int32_t));
            DataCopyPad(allRow[ti * TILE_ELEM], wsGm_[totalFlat + ti * TILE_ELEM], cp, pp);
        }
        inQ_.EnQue(allRow);
        LocalTensor<int32_t> allRowD = inQ_.DeQue<int32_t>();

        // K-way merge using calcBuf
        LocalTensor<int32_t> mBuf = calcBuf_.Get<int32_t>(TILE_ELEM * 2 * sizeof(int32_t));
        int64_t eaten[64] = {};
        for (int64_t outPos = 0; outPos < totalFlat; outPos++) {
            int32_t minVal = 2147483647;
            int64_t minTi = -1;
            for (int64_t ti = 0; ti < numTiles; ti++) {
                if (eaten[ti] < tlen[ti]) {
                    int32_t v = allExpD.GetValue(ti * TILE_ELEM + eaten[ti]);
                    if (v < minVal) { minVal = v; minTi = ti; }
                }
            }
            if (minTi < 0) break;
            mBuf.SetValue(outPos, minVal);
            mBuf.SetValue(TILE_ELEM + outPos, allRowD.GetValue(minTi * TILE_ELEM + eaten[minTi]));
            eaten[minTi]++;
        }

        // Write expanded_expert_idx
        LocalTensor<int32_t> oeOut = outQ_.AllocTensor<int32_t>();
        for (int64_t j = 0; j < outputNK; j++) {
            oeOut.SetValue(j, mBuf.GetValue(j));
        }
        outQ_.EnQue(oeOut);
        LocalTensor<int32_t> oeDq = outQ_.DeQue<int32_t>();
        cp.blockLen = static_cast<uint32_t>(outputNK * sizeof(int32_t));
        DataCopyPad(oeGm_[0], oeDq[0], cp);
        outQ_.FreeTensor(oeDq);

        // Scatter-invert
        LocalTensor<int32_t> orOut = outQ_.AllocTensor<int32_t>();
        Duplicate<int32_t>(orOut, -1, outputNK);
        for (int64_t i = 0; i < outputNK; i++) {
            int32_t dstP = mBuf.GetValue(TILE_ELEM + i);
            if (dstP >= 0 && dstP < static_cast<int32_t>(totalFlat)) {
                orOut.SetValue(dstP, static_cast<int32_t>(i));
            }
        }
        outQ_.EnQue(orOut);
        LocalTensor<int32_t> orDq = outQ_.DeQue<int32_t>();
        DataCopyPad(orGm_[0], orDq[0], cp);
        outQ_.FreeTensor(orDq);

        // Row gather
        for (int64_t p = 0; p < outputNK; p++) {
            int32_t srcIdx = mBuf.GetValue(TILE_ELEM + p);
            int64_t origRow = srcIdx % N;
            if (origRow < 0) origRow += N;

            LocalTensor<T> xRowL = inQ_.AllocTensor<T>();
            DataCopyParams cpRow;
            cpRow.blockCount = 1;
            cpRow.blockLen = static_cast<uint32_t>(H * sizeof(T));
            DataCopyPadParams ppRow{false, 0, 0, 0};
            DataCopyPad(xRowL[0], xGm_[origRow * H], cpRow, ppRow);
            inQ_.EnQue(xRowL);
            LocalTensor<T> xRowD = inQ_.DeQue<T>();
            DataCopyPad(oxGm_[p * H], xRowD[0], cpRow);
            inQ_.FreeTensor(xRowD);
        }

        inQ_.FreeTensor(allExpD);
        inQ_.FreeTensor(allRowD);
    }
}

// ============================================================================
// Process
// ============================================================================
template <typename T>
__aicore__ inline void KernelMoeInitRouting<T>::Process()
{
    if (GetBlockIdx() != 0) return;

    // Phase 1: Per-tile sort, write to workspace
    for (int64_t ti = 0; ti < td_.numTiles; ti++) {
        SortOneTile(ti);
    }
    PipeBarrier<PIPE_ALL>();

    // Phase 2: Merge + scatter-invert + row-gather
    MergeAndOutput();
}

