{"content": "/*
 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
 * Licensed under the CANN Open Software License Agreement Version 2.0.
 *
 * MoE Init Routing AscendC kernel.
 * Uses hardware Sort<float,true> for ascending sort of expert keys with
 * row_idx companion. Then scatter-invert + row-gather.
 *
 * Algorithm: Flatten [N,K] inputs → cast expert to fp32 → negate (ascending
 * via descending Sort) → Sort → negate back → scatter-invert → row-gather.
 */

#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t ONE_REPEAT_SORT_NUM = 32;
constexpr float MIN_FP32 = -3.4e38f;
constexpr int64_t UB_SORT_CAPACITY = 2048;

struct MoeInitRoutingTiling {
    int32_t N, K, H, totalFlat, outputNK, sortNum;
};

template <typename T>
class KernelMoeInitRouting {
public:
    __aicore__ inline KernelMoeInitRouting() {}
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR r, GM_ADDR e,
        GM_ADDR ox, GM_ADDR oder, GM_ADDR oe,
        GM_ADDR t, TPipe* pipeIn);
    __aicore__ inline void Process();

private:
    TPipe* pipe_;
    MoeInitRoutingTiling td_;

    GlobalTensor<T> xGm_;
    GlobalTensor<int32_t> rGm_;
    GlobalTensor<int32_t> eGm_;
    GlobalTensor<T> oxGm_;
    GlobalTensor<int32_t> orGm_;
    GlobalTensor<int32_t> oeGm_;

    TQue<QuePosition::VECIN, 1> inQ_;
    TQue<QuePosition::VECOUT, 1> outQ_;
    TBuf<TPosition::VECCALC> tmpBuf_;
    TBuf<TPosition::VECCALC> sortBuf_;
};

template <typename T>
__aicore__ inline void KernelMoeInitRouting<T>::Init(
    GM_ADDR x, GM_ADDR r, GM_ADDR e,
    GM_ADDR ox, GM_ADDR oder, GM_ADDR oe,
    GM_ADDR t, TPipe* pipeIn)
{
    pipe_ = pipeIn;
    auto* tl = reinterpret_cast<__gm__ MoeInitRoutingTiling*>(t);
    td_.N = tl->N;
    td_.K = tl->K;
    td_.H = tl->H;
    td_.totalFlat = tl->totalFlat;
    td_.outputNK = tl->outputNK;
    td_.sortNum = tl->sortNum;

    xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x), td_.N * td_.H);
    rGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(r), td_.totalFlat);
    eGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(e), td_.totalFlat);
    oxGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(ox), td_.outputNK * td_.H);
    orGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(oder), td_.outputNK);
    oeGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(oe), td_.outputNK);

    int64_t sortBufSize = td_.sortNum * sizeof(float) * 4;
    pipe_->InitBuffer(inQ_,   1, sortBufSize);
    pipe_->InitBuffer(outQ_,  1, sortBufSize);
    pipe_->InitBuffer(tmpBuf_, sortBufSize);
    pipe_->InitBuffer(sortBuf_, sortBufSize);
}

template <typename T>
__aicore__ inline void KernelMoeInitRouting<T>::Process()
{
    if (GetBlockIdx() != 0) return;

    int64_t totalFlat = td_.totalFlat;
    int64_t outputNK  = td_.outputNK;
    int64_t sortNum   = td_.sortNum;
    int64_t N         = td_.N;
    int64_t H         = td_.H;

    // ==============================================================
    // Phase 1: Sort expert keys ascending with row_idx companion
    // ==============================================================

    // Alloc input buffer: keys(float32) + values(uint32) interleaved
    LocalTensor<float> inL = inQ_.AllocTensor<float>();
    LocalTensor<float> keysFp32 = inL[0];
    LocalTensor<int32_t> keysInt = keysFp32.ReinterpretCast<int32_t>();
    LocalTensor<uint32_t> valsU32 = inL[sortNum].ReinterpretCast<uint32_t>();

    // CopyIn: expert keys as int32
    DataCopyParams cp;
    cp.blockCount = 1;
    cp.blockLen = static_cast<uint32_t>(totalFlat * sizeof(int32_t));
    DataCopyPadParams pp{false, 0, 0, 0};
    DataCopyPad(keysInt[0], eGm_[0], cp, pp);

    // CopyIn: row indices as int32
    {
        LocalTensor<int32_t> rTmp = valsU32.ReinterpretCast<int32_t>();
        DataCopyPad(rTmp[0], rGm_[0], cp, pp);
    }

    // Cast expert int32 → float32, negate for ascending sort
    Cast(keysFp32, keysInt, RoundMode::CAST_NONE, sortNum);
    Muls(keysFp32, keysFp32, static_cast<float>(-1.0), sortNum);

    // Pad tail elements with MIN_FP32
    int64_t dupNum = totalFlat % ONE_REPEAT_SORT_NUM;
    if (dupNum > 0) {
        int64_t dupIdx = totalFlat - dupNum;
        uint64_t mask0 = UINT64_MAX;
        mask0 = mask0 << dupNum;
        mask0 = mask0 & (UINT64_MAX >> ONE_REPEAT_SORT_NUM);
        uint64_t mask[2] = {mask0, 0};
        Duplicate(keysFp32[dupIdx], MIN_FP32, mask, 1, 1, 8);
    }

    // Concat → Sort<float,true> → Extract
    LocalTensor<float> concatL;
    LocalTensor<float> tmpSort = tmpBuf_.Get<float>(GetSortLen<float>(sortNum));
    Concat(concatL, keysFp32, tmpSort, sortNum / ONE_REPEAT_SORT_NUM);

    LocalTensor<float> sortedL = sortBuf_.Get<float>(GetSortLen<float>(sortNum));
    Sort<float, true>(sortedL, concatL, valsU32, tmpSort,
                      sortNum / ONE_REPEAT_SORT_NUM);

    // Extract sorted keys and values
    LocalTensor<float> outL = outQ_.AllocTensor<float>();
    LocalTensor<float> sortedKeys = outL[0];
    LocalTensor<uint32_t> sortedVals = outL[sortNum].ReinterpretCast<uint32_t>();
    Extract(sortedKeys, sortedVals, sortedL, sortNum / ONE_REPEAT_SORT_NUM);

    // Negate keys back (restore ascending), cast to int32
    Muls(sortedKeys, sortedKeys, static_cast<float>(-1.0), totalFlat);
    LocalTensor<int32_t> sortedKeysInt = sortedKeys.ReinterpretCast<int32_t>();
    Cast(sortedKeysInt, sortedKeys, RoundMode::CAST_ROUND, sortNum);

    // CopyOut sorted expert keys → expanded_expert_idx
    DataCopyParams cpOut;
    cpOut.blockCount = 1;
    cpOut.blockLen = static_cast<uint32_t>(outputNK * sizeof(int32_t));
    DataCopyPad(oeGm_[0], sortedKeysInt[0], cpOut);

    outQ_.EnQue<float>(outL);
    inQ_.FreeTensor(inL);

    // DeQue sorted output
    LocalTensor<float> outD = outQ_.DeQue<float>();
    PipeBarrier<PIPE_ALL>();

    // ==============================================================
    // Phase 2: Scatter-invert → expanded_row_idx
    // ==============================================================

    // sortedVals as int32 = dst_to_src
    LocalTensor<int32_t> dstToSrc = sortedVals.ReinterpretCast<int32_t>();

    // Init orGm_ to -1
    LocalTensor<int32_t> initBuf = inQ_.AllocTensor<int32_t>();
    Duplicate<int32_t>(initBuf, -1, outputNK);
    DataCopyParams cpInit;
    cpInit.blockCount = 1;
    cpInit.blockLen = static_cast<uint32_t>(outputNK * sizeof(int32_t));
    DataCopyPad(orGm_[0], initBuf[0], cpInit);
    inQ_.FreeTensor(initBuf);

    // Scatter: orGm_[dst_to_src[i]] = i
    for (int64_t i = 0; i < outputNK; i++) {
        int32_t dstP = dstToSrc.GetValue(i);
        if (dstP >= 0 && dstP < static_cast<int32_t>(totalFlat)) {
            orGm_.SetValue(dstP, static_cast<int32_t>(i));
        }
    }
    PipeBarrier<PIPE_ALL>();

    // ==============================================================
    // Phase 3: Row gather → expanded_x
    // ==============================================================
    for (int64_t p = 0; p < outputNK; p++) {
        int32_t srcIdx = dstToSrc.GetValue(p);
        int64_t origRow = srcIdx % N;
        if (origRow < 0) origRow += N;

        LocalTensor<T> xRow = inQ_.AllocTensor<T>();
        DataCopyParams cpRow;
        cpRow.blockCount = 1;
        cpRow.blockLen = static_cast<uint32_t>(H * sizeof(T));
        DataCopyPadParams ppRow{false, 0, 0, 0};
        DataCopyPad(xRow[0], xGm_[origRow * H], cpRow, ppRow);
        inQ_.EnQue(xRow);
        LocalTensor<T> xRowD = inQ_.DeQue<T>();
        DataCopyPad(oxGm_[p * H], xRowD[0], cpRow);
        inQ_.FreeTensor(xRowD);
    }

    outQ_.FreeTensor(outD);
}

