 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
 * Licensed under the CANN Open Software License Agreement Version 2.0.
 *
 * MoE Init Routing AscendC kernel.
 * Uses hardware Sort<float,true> + scatter-invert + row-gather.
 * Two modes: fullload (N*K≤2048, single-pass) & singlecore (>2048, multi-tile).
 */

#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t ONE_REPEAT_SORT_NUM = 32;
constexpr float MIN_FP32 = -3.4e38f;
constexpr int64_t UB_SORT_CAP = 2048;

struct MoeInitRoutingTiling {
    int32_t N, K, H, totalFlat, outputNK;
    int32_t sortNum, tileSortNum, numTiles, lastTileLen;
};

template <typename T>
class KernelMoeInitRouting {
public:
    __aicore__ inline KernelMoeInitRouting() {}
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR r, GM_ADDR e,
        GM_ADDR ox, GM_ADDR oder, GM_ADDR oe,
        GM_ADDR ws, GM_ADDR t, TPipe* pipeIn);
    __aicore__ inline void Process();

private:
    __aicore__ inline void FullLoadMode();
    __aicore__ inline void SingleCoreMode();

    TPipe* pipe_;
    MoeInitRoutingTiling td_;

    GlobalTensor<T> xGm_;
    GlobalTensor<int32_t> rGm_;
    GlobalTensor<int32_t> eGm_;
    GlobalTensor<T> oxGm_;
    GlobalTensor<int32_t> orGm_;
    GlobalTensor<int32_t> oeGm_;
    GlobalTensor<int32_t> wsGm_;

    TQue<QuePosition::VECIN, 1> inQ_;
    TQue<QuePosition::VECOUT, 1> outQ_;
    TBuf<TPosition::VECCALC> tmpBuf_;
    TBuf<TPosition::VECCALC> sortBuf_;
};

template <typename T>
__aicore__ inline void KernelMoeInitRouting<T>::Init(
    GM_ADDR x, GM_ADDR r, GM_ADDR e,
    GM_ADDR ox, GM_ADDR oder, GM_ADDR oe,
    GM_ADDR ws, GM_ADDR t, TPipe* pipeIn)
{
    pipe_ = pipeIn;
    auto* tl = reinterpret_cast<__gm__ MoeInitRoutingTiling*>(t);
    td_.N = tl->N;
    td_.K = tl->K;
    td_.H = tl->H;
    td_.totalFlat = tl->totalFlat;
    td_.outputNK = tl->outputNK;
    td_.sortNum = tl->sortNum;
    td_.tileSortNum = tl->tileSortNum;
    td_.numTiles = tl->numTiles;
    td_.lastTileLen = tl->lastTileLen;

    xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x), td_.N * td_.H);
    rGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(r), td_.totalFlat);
    eGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(e), td_.totalFlat);
    oxGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(ox), td_.outputNK * td_.H);
    orGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(oder), td_.outputNK);
    oeGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(oe), td_.outputNK);

    int64_t wsSize = td_.numTiles * td_.tileSortNum * 2 + td_.totalFlat + 64;
    wsGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(ws), wsSize);

    int64_t bufSz = td_.sortNum * sizeof(float) * 4;
    pipe_->InitBuffer(inQ_,   1, bufSz);
    pipe_->InitBuffer(outQ_,  1, bufSz);
    pipe_->InitBuffer(tmpBuf_, bufSz);
    pipe_->InitBuffer(sortBuf_, bufSz);
}

// ============================================================================
// FullLoadMode: all N*K ≤ 2048, single-pass hardware Sort
// ============================================================================
template <typename T>
__aicore__ inline void KernelMoeInitRouting<T>::FullLoadMode()
{
    int64_t totalFlat = td_.totalFlat;
    int64_t outputNK  = td_.outputNK;
    int64_t sortNum   = td_.sortNum;
    int64_t N         = td_.N;
    int64_t H         = td_.H;

    // Alloc: keys(float32) + values(uint32) interleaved
    LocalTensor<float> inL = inQ_.AllocTensor<float>();
    LocalTensor<float> keysFp32 = inL[0];
    LocalTensor<int32_t> keysInt = keysFp32.ReinterpretCast<int32_t>();
    LocalTensor<uint32_t> valsU32 = inL[sortNum].ReinterpretCast<uint32_t>();

    DataCopyParams cp;
    cp.blockCount = 1;
    cp.blockLen = static_cast<uint32_t>(totalFlat * sizeof(int32_t));
    DataCopyPadParams pp{false, 0, 0, 0};

    // CopyIn expert keys
    DataCopyPad(keysInt[0], eGm_[0], cp, pp);
    // CopyIn row values
    {
        LocalTensor<int32_t> rTmp = valsU32.ReinterpretCast<int32_t>();
        DataCopyPad(rTmp[0], rGm_[0], cp, pp);
    }

    // Cast int32→float32, negate for ascending
    Cast(keysFp32, keysInt, RoundMode::CAST_NONE, sortNum);
    Muls(keysFp32, keysFp32, static_cast<float>(-1.0), sortNum);

    // Pad tail with MIN_FP32
    int64_t dupN = totalFlat % ONE_REPEAT_SORT_NUM;
    if (dupN > 0) {
        int64_t dupIdx = totalFlat - dupN;
        uint64_t mask0 = UINT64_MAX;
        mask0 = mask0 << dupN;
        mask0 = mask0 & (UINT64_MAX >> ONE_REPEAT_SORT_NUM);
        uint64_t mask[2] = {mask0, 0};
        Duplicate(keysFp32[dupIdx], MIN_FP32, mask, 1, 1, 8);
    }

    // Concat → Sort<float,true> → Extract
    LocalTensor<float> concatL;
    LocalTensor<float> tmpSort = tmpBuf_.Get<float>(GetSortLen<float>(sortNum));
    Concat(concatL, keysFp32, tmpSort, sortNum / ONE_REPEAT_SORT_NUM);

    LocalTensor<float> sortedL = sortBuf_.Get<float>(GetSortLen<float>(sortNum));
    Sort<float, true>(sortedL, concatL, valsU32, tmpSort,
                      sortNum / ONE_REPEAT_SORT_NUM);

    LocalTensor<float> outL = outQ_.AllocTensor<float>();
    LocalTensor<float> sortedKeys = outL[0];
    LocalTensor<uint32_t> sortedVals = outL[sortNum].ReinterpretCast<uint32_t>();
    Extract(sortedKeys, sortedVals, sortedL, sortNum / ONE_REPEAT_SORT_NUM);

    // Negate keys back, cast to int32
    Muls(sortedKeys, sortedKeys, static_cast<float>(-1.0), totalFlat);
    LocalTensor<int32_t> sortedKeysInt = sortedKeys.ReinterpretCast<int32_t>();
    Cast(sortedKeysInt, sortedKeys, RoundMode::CAST_ROUND, sortNum);

    // CopyOut sorted expert keys → oeGm_
    DataCopyParams cpOut;
    cpOut.blockCount = 1;
    cpOut.blockLen = static_cast<uint32_t>(outputNK * sizeof(int32_t));
    DataCopyPad(oeGm_[0], sortedKeysInt[0], cpOut);

    outQ_.EnQue<float>(outL);
    inQ_.FreeTensor(inL);

    // DeQue sorted output
    LocalTensor<float> outD = outQ_.DeQue<float>();

    // sortedVals as int32 = dst_to_src
    LocalTensor<int32_t> dstToSrc = sortedVals.ReinterpretCast<int32_t>();

    // Init orGm_ to -1
    LocalTensor<int32_t> initB = inQ_.AllocTensor<int32_t>();
    Duplicate<int32_t>(initB, -1, outputNK);
    DataCopyParams cpInit;
    cpInit.blockCount = 1;
    cpInit.blockLen = static_cast<uint32_t>(outputNK * sizeof(int32_t));
    DataCopyPad(orGm_[0], initB[0], cpInit);
    inQ_.FreeTensor(initB);

    // Scatter: orGm_[dst_to_src[i]] = i
    for (int64_t i = 0; i < outputNK; i++) {
        int32_t dstP = dstToSrc.GetValue(i);
        if (dstP >= 0 && dstP < static_cast<int32_t>(totalFlat)) {
            orGm_.SetValue(dstP, static_cast<int32_t>(i));
        }
    }
    PipeBarrier<PIPE_ALL>();

    // Row gather: ox[p, :] = x[dst_to_src[p] % N, :]
    for (int64_t p = 0; p < outputNK; p++) {
        int32_t srcIdx = dstToSrc.GetValue(p);
        int64_t origRow = srcIdx % N;
        if (origRow < 0) origRow += N;

        LocalTensor<T> xRow = inQ_.AllocTensor<T>();
        DataCopyParams cpR;
        cpR.blockCount = 1;
        cpR.blockLen = static_cast<uint32_t>(H * sizeof(T));
        DataCopyPadParams ppR{false, 0, 0, 0};
        DataCopyPad(xRow[0], xGm_[origRow * H], cpR, ppR);
        inQ_.EnQue(xRow);
        LocalTensor<T> xRowD = inQ_.DeQue<T>();
        DataCopyPad(oxGm_[p * H], xRowD[0], cpR);
        inQ_.FreeTensor(xRowD);
    }

    outQ_.FreeTensor(outD);
}

// ============================================================================
// SingleCoreMode: per-tile hardware Sort → K-way merge → scatter/gather
// ============================================================================
template <typename T>
__aicore__ inline void KernelMoeInitRouting<T>::SingleCoreMode()
{
    int64_t totalFlat = td_.totalFlat;
    int64_t outputNK  = td_.outputNK;
    int64_t sortNum   = td_.sortNum;
    int64_t tileSn    = td_.tileSortNum;
    int64_t numTiles  = td_.numTiles;
    int64_t N         = td_.N;
    int64_t H         = td_.H;

    // Workspace layout:
    //   [0, numTiles*tileSn): expert keys per tile
    //   [numTiles*tileSn, 2*numTiles*tileSn): row values per tile
    int64_t wsExpBase = 0;
    int64_t wsRowBase = numTiles * tileSn;
    int64_t wsMergedRow = wsRowBase + numTiles * tileSn;

    // Phase 1: Per-tile hardware Sort
    for (int64_t ti = 0; ti < numTiles; ti++) {
        int64_t start = ti * UB_SORT_CAP;
        int64_t len = (ti == numTiles - 1) ? td_.lastTileLen : UB_SORT_CAP;
        if (len <= 0) continue;

        LocalTensor<float> inL = inQ_.AllocTensor<float>();
        LocalTensor<float> keysFp32 = inL[0];
        LocalTensor<int32_t> keysInt = keysFp32.ReinterpretCast<int32_t>();
        LocalTensor<uint32_t> valsU32 = inL[tileSn].ReinterpretCast<uint32_t>();

        DataCopyParams cp;
        cp.blockCount = 1;
        cp.blockLen = static_cast<uint32_t>(len * sizeof(int32_t));
        DataCopyPadParams pp{false, 0, 0, 0};
        DataCopyPad(keysInt[0], eGm_[start], cp, pp);
        {
            LocalTensor<int32_t> rTmp = valsU32.ReinterpretCast<int32_t>();
            DataCopyPad(rTmp[0], rGm_[start], cp, pp);
        }

        Cast(keysFp32, keysInt, RoundMode::CAST_NONE, tileSn);
        Muls(keysFp32, keysFp32, static_cast<float>(-1.0), tileSn);

        int64_t dupN = len % ONE_REPEAT_SORT_NUM;
        if (dupN > 0) {
            int64_t dupIdx = len - dupN;
            uint64_t mask0 = UINT64_MAX;
            mask0 = mask0 << dupN;
            mask0 = mask0 & (UINT64_MAX >> ONE_REPEAT_SORT_NUM);
            uint64_t mask[2] = {mask0, 0};
            Duplicate(keysFp32[dupIdx], MIN_FP32, mask, 1, 1, 8);
        }

        LocalTensor<float> concatL;
        LocalTensor<float> tmpSort = tmpBuf_.Get<float>(GetSortLen<float>(tileSn));
        Concat(concatL, keysFp32, tmpSort, tileSn / ONE_REPEAT_SORT_NUM);

        LocalTensor<float> sortedL = sortBuf_.Get<float>(GetSortLen<float>(tileSn));
        Sort<float, true>(sortedL, concatL, valsU32, tmpSort,
                          tileSn / ONE_REPEAT_SORT_NUM);

        LocalTensor<float> outL = outQ_.AllocTensor<float>();
        LocalTensor<float> sortedKeys = outL[0];
        LocalTensor<uint32_t> sortedVals = outL[tileSn].ReinterpretCast<uint32_t>();
        Extract(sortedKeys, sortedVals, sortedL, tileSn / ONE_REPEAT_SORT_NUM);

        Muls(sortedKeys, sortedKeys, static_cast<float>(-1.0), len);
        LocalTensor<int32_t> keysIntOut = sortedKeys.ReinterpretCast<int32_t>();
        Cast(keysIntOut, sortedKeys, RoundMode::CAST_ROUND, tileSn);
        LocalTensor<int32_t> valsIntOut = sortedVals.ReinterpretCast<int32_t>();

        // Write to workspace
        DataCopyParams cpOut;
        cpOut.blockCount = 1;
        cpOut.blockLen = static_cast<uint32_t>(len * sizeof(int32_t));
        DataCopyPad(wsGm_[wsExpBase + ti * tileSn], keysIntOut[0], cpOut);
        DataCopyPad(wsGm_[wsRowBase + ti * tileSn], valsIntOut[0], cpOut);

        outQ_.EnQue<float>(outL);
        inQ_.FreeTensor(inL);
        LocalTensor<float> outD = outQ_.DeQue<float>();
        outQ_.FreeTensor(outD);
    }
    PipeBarrier<PIPE_ALL>();

    // Phase 2: K-way merge (scalar GM reads from sorted workspace)
    int64_t ptrs[64], ends[64], rowPtrs[64];
    for (int64_t ti = 0; ti < numTiles; ti++) {
        ptrs[ti] = wsExpBase + ti * tileSn;
        int64_t tlen = (ti == numTiles - 1) ? td_.lastTileLen : UB_SORT_CAP;
        ends[ti] = wsExpBase + ti * tileSn + tlen;
        rowPtrs[ti] = wsRowBase + ti * tileSn;
    }

    for (int64_t outPos = 0; outPos < totalFlat; outPos++) {
        int32_t minVal = 2147483647;
        int64_t minTi = -1;
        for (int64_t ti = 0; ti < numTiles; ti++) {
            if (ptrs[ti] < ends[ti]) {
                int32_t v = wsGm_.GetValue(ptrs[ti]);
                if (v < minVal) { minVal = v; minTi = ti; }
            }
        }
        if (minTi < 0) break;
        oeGm_.SetValue(outPos, minVal);
        int64_t rowOff = ptrs[minTi] - (wsExpBase + minTi * tileSn);
        wsGm_.SetValue(wsMergedRow + outPos,
            wsGm_.GetValue(rowPtrs[minTi] + rowOff));
        ptrs[minTi]++;
    }
    PipeBarrier<PIPE_ALL>();

    // Phase 3: Scatter-invert
    // Init orGm_ to -1
    LocalTensor<int32_t> initB = inQ_.AllocTensor<int32_t>();
    for (int64_t done = 0; done < outputNK; ) {
        int64_t cur = (outputNK - done > tileSn) ? tileSn : (outputNK - done);
        Duplicate<int32_t>(initB, -1, cur);
        DataCopyParams cpI;
        cpI.blockCount = 1;
        cpI.blockLen = static_cast<uint32_t>(cur * sizeof(int32_t));
        DataCopyPad(orGm_[done], initB[0], cpI);
        done += cur;
    }
    inQ_.FreeTensor(initB);

    for (int64_t i = 0; i < outputNK; i++) {
        int32_t dstP = wsGm_.GetValue(wsMergedRow + i);
        if (dstP >= 0 && dstP < static_cast<int32_t>(totalFlat)) {
            orGm_.SetValue(dstP, static_cast<int32_t>(i));
        }
    }
    PipeBarrier<PIPE_ALL>();

    // Phase 4: Row gather
    for (int64_t p = 0; p < outputNK; p++) {
        int32_t srcIdx = wsGm_.GetValue(wsMergedRow + p);
        int64_t origRow = srcIdx % N;
        if (origRow < 0) origRow += N;

        LocalTensor<T> xRow = inQ_.AllocTensor<T>();
        DataCopyParams cpR;
        cpR.blockCount = 1;
        cpR.blockLen = static_cast<uint32_t>(H * sizeof(T));
        DataCopyPadParams ppR{false, 0, 0, 0};
        DataCopyPad(xRow[0], xGm_[origRow * H], cpR, ppR);
        inQ_.EnQue(xRow);
        LocalTensor<T> xRowD = inQ_.DeQue<T>();
        DataCopyPad(oxGm_[p * H], xRowD[0], cpR);
        inQ_.FreeTensor(xRowD);
    }
}

// ============================================================================
// Process: route to mode
// ============================================================================
template <typename T>
__aicore__ inline void KernelMoeInitRouting<T>::Process()
{
    if (GetBlockIdx() != 0) return;
    if (td_.numTiles == 1) {
        FullLoadMode();
    } else {
        SingleCoreMode();
    }
}

