 *
 * MoEInitRouting host-side: tiling computation + kernel launch.
 * Uses hardware Sort instruction for sorting, two modes based on N*K.
 */

#include <algorithm>
#include <cstring>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_moe_init_routing_fp16.h"
#include "aclrtlaunch_moe_init_routing_fp32.h"
#include "aclrtlaunch_moe_init_routing_bf16.h"

namespace ascend_kernel {

struct MoeInitRoutingTiling {
    int32_t N, K, H, totalFlat, outputNK;
    int32_t sortNum, tileSortNum, numTiles, lastTileLen;
};

std::tuple<at::Tensor, at::Tensor, at::Tensor> moe_init_routing(
    const at::Tensor& x, const at::Tensor& row_idx,
    const at::Tensor& expert_idx, int64_t active_num)
{
    TORCH_CHECK(x.dim() == 2, "x must be 2D (N, H)");
    TORCH_CHECK(row_idx.dim() == 2, "row_idx must be 2D (N, K)");
    TORCH_CHECK(expert_idx.dim() == 2, "expert_idx must be 2D (N, K)");
    TORCH_CHECK(row_idx.size(0) == expert_idx.size(0) &&
                row_idx.size(1) == expert_idx.size(1),
                "row_idx and expert_idx must have same shape");
    TORCH_CHECK(x.size(0) == expert_idx.size(0),
                "x and expert_idx must have same N dimension");

    int64_t N = x.size(0);
    int64_t H = x.size(1);
    int64_t K = expert_idx.size(1);
    int64_t totalFlat = N * K;
    int64_t outputNK = active_num * K;

    TORCH_CHECK(x.scalar_type() == at::kFloat ||
                x.scalar_type() == at::kHalf ||
                x.scalar_type() == at::kBFloat16,
                "Unsupported x dtype, must be float32/float16/bfloat16");

    // Allocate output tensors
    at::Tensor expanded_x = at::empty({outputNK, H}, x.options());
    at::Tensor expanded_row_idx = at::empty({outputNK},
        x.options().dtype(at::kInt));
    at::Tensor expanded_expert_idx = at::empty({outputNK},
        x.options().dtype(at::kInt));

    constexpr int64_t ONE_REPEAT_SORT_NUM = 32;
    constexpr int64_t UB_SORT_CAP = 2048;

    // Tile sort parameters
    int64_t numTiles = (totalFlat + UB_SORT_CAP - 1) / UB_SORT_CAP;
    if (numTiles < 1) numTiles = 1;
    int64_t lastTileLen = totalFlat - (numTiles - 1) * UB_SORT_CAP;

    // Full sort size for single pass (used in FullLoadMode)
    int64_t sortNum = ((totalFlat + ONE_REPEAT_SORT_NUM - 1)
                        / ONE_REPEAT_SORT_NUM) * ONE_REPEAT_SORT_NUM;

    // Per-tile sort size
    int64_t tileSortNum = ((UB_SORT_CAP + ONE_REPEAT_SORT_NUM - 1)
                            / ONE_REPEAT_SORT_NUM) * ONE_REPEAT_SORT_NUM;

    // Tiling struct
    MoeInitRoutingTiling tiling;
    tiling.N = static_cast<int32_t>(N);
    tiling.K = static_cast<int32_t>(K);
    tiling.H = static_cast<int32_t>(H);
    tiling.totalFlat = static_cast<int32_t>(totalFlat);
    tiling.outputNK = static_cast<int32_t>(outputNK);
    tiling.sortNum = static_cast<int32_t>(sortNum);
    tiling.tileSortNum = static_cast<int32_t>(tileSortNum);
    tiling.numTiles = static_cast<int32_t>(numTiles);
    tiling.lastTileLen = static_cast<int32_t>(lastTileLen);

    // Copy tiling to device
    at::Tensor tilingCpu = at::empty(
        {static_cast<int64_t>(sizeof(MoeInitRoutingTiling))},
        at::device(at::kCPU).dtype(at::kByte));
    *reinterpret_cast<MoeInitRoutingTiling*>(tilingCpu.data_ptr()) = tiling;
    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);

    // Workspace layout: [expert_per_tile*Ntiles | row_per_tile*Ntiles | merged]
    int64_t wsSize = numTiles * tileSortNum * sizeof(int32_t) * 2
                     + totalFlat * sizeof(int32_t) + 4096;
    at::Tensor workspace = at::empty({wsSize},
        at::device(at::kPrivateUse1).dtype(at::kByte));

    // Launch kernel
    uint32_t blockDim = 1;
    if (x.scalar_type() == at::kHalf) {
        EXEC_KERNEL_CMD(moe_init_routing_fp16, blockDim,
            x, row_idx, expert_idx, expanded_x, expanded_row_idx,
            expanded_expert_idx, workspace, tilingNpu);
    } else if (x.scalar_type() == at::kFloat) {
        EXEC_KERNEL_CMD(moe_init_routing_fp32, blockDim,
            x, row_idx, expert_idx, expanded_x, expanded_row_idx,
            expanded_expert_idx, workspace, tilingNpu);
    } else {
        EXEC_KERNEL_CMD(moe_init_routing_bf16, blockDim,
            x, row_idx, expert_idx, expanded_x, expanded_row_idx,
            expanded_expert_idx, workspace, tilingNpu);
    }

    return std::make_tuple(expanded_x, expanded_row_idx, expanded_expert_idx);
}

}  // namespace ascend_kernel
