90	template <typename T>
91	__aicore__ inline void KernelMoeInitRouting<T>::SortTile(
92	    int64_t start, int64_t len, int64_t ti)
93	{
94	    int64_t K = td_.K;
95	    int64_t expertWsBase = td_.numTiles * TILE_ELEM;
96	    LocalTensor<int32_t> buf = sortBufQ_.AllocTensor<int32_t>();
97	
98	    /* Load flattened [N,K]→[N*K] expert+row into UB */
99	    for (int64_t j = 0; j < len; j++) {
100	        int64_t p = start + j;
101	        int64_t r = p / K;
102	        int64_t c = p % K;
103	        buf.SetValue(j, expertIdxGm_.GetValue(r * K + c));
104	        buf.SetValue(TILE_ELEM + j, rowIdxGm_.GetValue(r * K + c));
105	    }
106	
107	    /* Insertion sort by expert value (ascending, stable) */
108	    for (int64_t i = 1; i < len; i++) {
109	        int32_t keyE = buf.GetValue(i);
110	        int32_t keyR = buf.GetValue(TILE_ELEM + i);
111	        int64_t jj = i - 1;
112	        while (jj >= 0 && buf.GetValue(jj) > keyE) {
113	            buf.SetValue(jj + 1, buf.GetValue(jj));
114	            buf.SetValue(TILE_ELEM + jj + 1,
115	                buf.GetValue(TILE_ELEM + jj));
116	            jj--;
117	        }
118	        buf.SetValue(jj + 1, keyE);
119	        buf.SetValue(TILE_ELEM + jj + 1, keyR);
120	    }
121	
122	    /* Write sorted results to output and workspace */
123	    for (int64_t j = 0; j < len; j++) {
124	        int32_t ev = buf.GetValue(j);
125	        int32_t rv = buf.GetValue(TILE_ELEM + j);
126	        expandedExpertIdxGm_.SetValue(start + j, ev);
127	        expandedRowIdxGm_.SetValue(start + j, rv);
128	        /* Workspace: expert at upper half, row at lower half */
129	        wsGm_.SetValue(expertWsBase + ti * TILE_ELEM + j, ev);
130	        wsGm_.SetValue(ti * TILE_ELEM + j, rv);
131	    }
132	
133	    sortBufQ_.FreeTensor(buf);
134	}
