137	__aicore__ inline void KernelMoeInitRouting<T>::MergeTiles(int64_t totalFlat)
138	{
139	    int64_t expertBase = td_.numTiles * TILE_ELEM;
140	
141	    if (td_.numTiles <= 1) {
142	        /* Single tile: just copy from workspace expert region */
143	        for (int64_t j = 0; j < totalFlat; j++) {
144	            expandedExpertIdxGm_.SetValue(j,
145	                wsGm_.GetValue(expertBase + j));
146	            expandedRowIdxGm_.SetValue(j,
147	                wsGm_.GetValue(j));
148	        }
149	        return;
150	    }
151	
152	    /* K-way merge: track position in each sorted tile */
153	    int64_t ptrs[55];
154	    int64_t ends[55];
155	    for (int64_t i = 0; i < td_.numTiles; i++) {
156	        ptrs[i] = expertBase + i * TILE_ELEM;
157	        int64_t tlen = (i == td_.numTiles - 1) ? td_.lastTileLen : TILE_ELEM;
158	        ends[i] = expertBase + i * TILE_ELEM + tlen;
159	    }
160	
161	    for (int64_t outPos = 0; outPos < totalFlat; outPos++) {
162	        int32_t minVal = 2147483647;
163	        int64_t minTile = -1;
164	        for (int64_t ti = 0; ti < td_.numTiles; ti++) {
165	            if (ptrs[ti] < ends[ti]) {
166	                int32_t v = wsGm_.GetValue(ptrs[ti]);
167	                if (v < minVal) { minVal = v; minTile = ti; }
168	            }
169	        }
170	        if (minTile < 0) break;
171	
172	        int64_t off = ptrs[minTile] - expertBase - minTile * TILE_ELEM;
173	        expandedExpertIdxGm_.SetValue(outPos, minVal);
174	        expandedRowIdxGm_.SetValue(outPos,
175	            wsGm_.GetValue(minTile * TILE_ELEM + off));
176	        ptrs[minTile]++;
177	    }
178	}
