182	{
183	    /* Save dst_to_src (currently in ExpandedRowIdx) to workspace temp area */
184	    int64_t expertBase = td_.numTiles * TILE_ELEM;
185	    int64_t wsSaveBase = expertBase + td_.numTiles * TILE_ELEM;
