195	        int64_t cur = (totalFlat - done > TILE_ELEM) ? TILE_ELEM : (totalFlat - done);
196	        Duplicate<int32_t>(initBuf, -1, cur);
197	        DataCopy(expandedRowIdxGm_[done], initBuf, cur);
198	        done += cur;
199	    }
200	    sortBufQ_.FreeTensor(initBuf);
